INSERT INTO `problems` VALUES (1, '2026-06-03 11:49:06.254', '2026-06-04 00:14:58.533', NULL, 'A+B Problem', 'a-plus-b', '输入两个整数 a 和 b，计算它们的和并输出。这是所有 OJ 系统的经典入门题，用于熟悉 OJ 的输入输出格式。', '一行，包含两个整数 a 和 b，用空格分隔。\n数据范围：-10^9 ≤ a, b ≤ 10^9', '一行，输出一个整数，表示 a + b 的计算结果。', 'Easy', 1000, 128, '注意数据范围，部分语言需要使用 64 位整数类型避免溢出。', 1, 12, 8);
INSERT INTO `problems` VALUES (2, '2026-06-03 14:26:25.385', '2026-06-03 18:09:50.672', NULL, 'Hello World', 'Hello World', '输出“Hello World”', '', 'Hello World', 'Easy', 1000, 128, '', 1, 14, 8);
INSERT INTO `problems` VALUES (3, '2026-06-03 16:23:06.238', '2026-06-03 16:29:58.913', NULL, '九九乘法表', 'multiplication table', '输出九九乘法表', '一个整数 n（ n ≤ 9 ）', '输出到n*n的九九乘法表', 'Easy', 1000, 128, '', 1, 3, 1);
INSERT INTO `problems` VALUES (4, '2026-06-03 17:58:45.954', '2026-06-04 00:14:58.544', NULL, '两数之差', 'a-minus-b', '输入两个整数 a 和 b，计算 a - b 的结果并输出。', '一行，包含两个整数 a 和 b，用空格分隔。\n数据范围：-10^9 ≤ a, b ≤ 10^9', '一行，输出一个整数，表示 a - b 的结果。', 'Easy', 1000, 128, '注意负数的情况，结果可能为负。', 1, 2, 1);
INSERT INTO `problems` VALUES (5, '2026-06-03 17:58:45.957', '2026-06-04 00:14:58.554', NULL, '两数乘积', 'a-multiply-b', '输入两个整数 a 和 b，计算它们的乘积并输出。', '一行，包含两个整数 a 和 b，用空格分隔。\n数据范围：-10^6 ≤ a, b ≤ 10^6', '一行，输出一个整数，表示 a × b 的结果。', 'Easy', 1000, 128, '大数相乘时注意溢出问题，建议使用长整型。', 1, 0, 0);
INSERT INTO `problems` VALUES (6, '2026-06-03 17:58:45.958', '2026-06-04 00:14:58.563', NULL, '整数除法', 'integer-division', '输入两个正整数 a 和 b，计算 a 除以 b 的整数商（向下取整）。', '一行，包含两个正整数 a 和 b，用空格分隔。\n数据范围：1 ≤ b ≤ a ≤ 10^9', '一行，输出一个整数，表示 a ÷ b 的整数商。', 'Easy', 1000, 128, '题目保证 b 不为 0，无需处理除零错误。', 1, 0, 0);
INSERT INTO `problems` VALUES (7, '2026-06-03 17:58:45.960', '2026-06-04 00:14:58.572', NULL, '圆的面积', 'circle-area', '输入圆的半径 r，计算圆的面积，π 取 3.1415926。', '一行，一个浮点数 r，表示圆的半径。\n数据范围：0 < r ≤ 1000', '一行，输出圆的面积，保留 6 位小数。', 'Easy', 1000, 128, '面积公式：S = π × r²，注意浮点数精度问题。', 1, 0, 0);
INSERT INTO `problems` VALUES (8, '2026-06-03 17:58:45.961', '2026-06-04 00:14:58.583', NULL, '交换两个数', 'swap-two-numbers', '输入两个整数 a 和 b，交换它们的值后输出。', '一行，包含两个整数 a 和 b，用空格分隔。', '一行，输出交换后的两个整数，用空格分隔。', 'Easy', 1000, 128, '可以使用临时变量，也可以用算术运算实现不使用临时变量的交换。', 1, 0, 0);
INSERT INTO `problems` VALUES (9, '2026-06-03 17:58:45.963', '2026-06-04 00:14:58.593', NULL, 'Hello World', 'hello-world', '输出一行字符串\"Hello World!\"。', '无输入。', '一行，内容为 Hello World!', 'Easy', 1000, 128, '注意大小写和标点符号，必须完全匹配。', 1, 0, 0);
INSERT INTO `problems` VALUES (10, '2026-06-03 17:58:45.965', '2026-06-04 00:14:58.602', NULL, '三个数求和', 'sum-of-three-numbers', '输入三个整数，计算它们的和并输出。', '一行，包含三个整数，用空格分隔。', '一行，输出三个数的和。', 'Easy', 1000, 128, '可以依次相加，也可以一次性计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (11, '2026-06-03 17:58:45.966', '2026-06-04 00:14:58.611', NULL, '求绝对值', 'absolute-value', '输入一个整数，输出它的绝对值。', '一行，一个整数 n。\n数据范围：-10^9 ≤ n ≤ 10^9', '一行，输出 n 的绝对值。', 'Easy', 1000, 128, '正数的绝对值是它本身，负数的绝对值是它的相反数，0 的绝对值是 0。', 1, 0, 0);
INSERT INTO `problems` VALUES (12, '2026-06-03 17:58:45.968', '2026-06-04 00:14:58.620', NULL, '摄氏度转华氏度', 'celsius-to-fahrenheit', '输入摄氏度 C，转换为华氏度 F 输出。转换公式：F = C × 9/5 + 32。', '一行，一个浮点数 C，表示摄氏度。', '一行，输出转换后的华氏度，保留 2 位小数。', 'Easy', 1000, 128, '注意运算顺序，先乘除后加减。', 1, 0, 0);
INSERT INTO `problems` VALUES (13, '2026-06-03 17:58:45.970', '2026-06-04 00:14:58.628', NULL, '判断奇偶', 'judge-odd-even', '输入一个整数，判断它是奇数还是偶数。', '一行，一个整数 n。', '如果是偶数，输出\"Even\"；如果是奇数，输出\"Odd\"。', 'Easy', 1000, 128, '能被 2 整除的数是偶数，即 n % 2 == 0。', 1, 0, 0);
INSERT INTO `problems` VALUES (14, '2026-06-03 17:58:45.972', '2026-06-04 00:14:58.638', NULL, '三个数的最大值', 'max-of-three-numbers', '输入三个整数，输出其中最大的数。', '一行，包含三个整数，用空格分隔。', '一行，输出三个数中的最大值。', 'Easy', 1000, 128, '可以先比较前两个数得到较大值，再和第三个数比较。', 1, 0, 0);
INSERT INTO `problems` VALUES (15, '2026-06-03 17:58:45.974', '2026-06-04 00:14:58.646', NULL, '三个数排序', 'sort-three-numbers', '输入三个整数，按从小到大的顺序输出。', '一行，包含三个整数，用空格分隔。', '一行，输出排序后的三个整数，用空格分隔。', 'Easy', 1000, 128, '可以通过多次比较交换实现排序。', 1, 0, 0);
INSERT INTO `problems` VALUES (16, '2026-06-03 17:58:45.975', '2026-06-04 00:14:58.657', NULL, '判断闰年', 'leap-year-judge', '输入一个年份，判断是否为闰年。闰年规则：能被 4 整除但不能被 100 整除，或者能被 400 整除。', '一行，一个正整数 year，表示年份。', '如果是闰年，输出\"Leap Year\"；否则输出\"Common Year\"。', 'Easy', 1000, 128, '注意整百年份必须能被 400 整除才是闰年，比如 1900 年不是闰年，2000 年是闰年。', 1, 0, 0);
INSERT INTO `problems` VALUES (17, '2026-06-03 17:58:45.977', '2026-06-04 00:14:58.666', NULL, '成绩等级转换', 'score-to-grade', '输入一个 0-100 的整数成绩，转换为等级：90 分及以上为 A，80-89 为 B，70-79 为 C，60-69 为 D，60 以下为 E。', '一行，一个整数 score，0 ≤ score ≤ 100。', '一行，输出对应的等级字母（A/B/C/D/E）。', 'Easy', 1000, 128, '使用多分支条件判断，注意区间的边界值。', 1, 0, 0);
INSERT INTO `problems` VALUES (18, '2026-06-03 17:58:45.979', '2026-06-04 00:14:58.675', NULL, '判断正负数', 'judge-positive-negative', '输入一个整数，判断它是正数、负数还是零。', '一行，一个整数 n。', '正数输出\"Positive\"，负数输出\"Negative\"，零输出\"Zero\"。', 'Easy', 1000, 128, '大于 0 是正数，小于 0 是负数，等于 0 是零。', 1, 0, 0);
INSERT INTO `problems` VALUES (19, '2026-06-03 17:58:45.980', '2026-06-04 00:14:58.682', NULL, '比较两个数大小', 'compare-two-numbers', '输入两个整数 a 和 b，比较它们的大小。', '一行，包含两个整数 a 和 b，用空格分隔。', '如果 a > b 输出\">\"，a < b 输出\"<\"，相等输出\"=\"。', 'Easy', 1000, 128, '三种情况分别判断即可。', 1, 0, 0);
INSERT INTO `problems` VALUES (20, '2026-06-03 17:58:45.982', '2026-06-04 00:14:58.691', NULL, '三角形合法性判定', 'triangle-validity', '输入三个正整数，判断它们能否构成三角形。三角形规则：任意两边之和大于第三边。', '一行，包含三个正整数 a, b, c，用空格分隔。', '能构成三角形输出\"Yes\"，否则输出\"No\"。', 'Easy', 1000, 128, '只需判断最小的两边之和大于最大的边即可，无需判断所有组合。', 1, 0, 0);
INSERT INTO `problems` VALUES (21, '2026-06-03 17:58:45.984', '2026-06-04 00:14:58.700', NULL, '数字转星期', 'number-to-weekday', '输入 1-7 的整数，输出对应的星期几：1=Monday，2=Tuesday，3=Wednesday，4=Thursday，5=Friday，6=Saturday，7=Sunday。', '一行，一个整数 n，1 ≤ n ≤ 7。', '一行，输出对应的星期英文单词。', 'Easy', 1000, 128, '可以使用多分支 if 或者 switch 语句实现。', 1, 0, 0);
INSERT INTO `problems` VALUES (22, '2026-06-03 17:58:45.985', '2026-06-04 00:14:58.709', NULL, '分段函数计算', 'piecewise-function', '计算分段函数的值：\n当 x < 0 时，y = -x\n当 0 ≤ x < 10 时，y = x²\n当 x ≥ 10 时，y = 2x + 5', '一行，一个整数 x。', '一行，输出 y 的值。', 'Easy', 1000, 128, '根据 x 的范围选择对应的公式计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (23, '2026-06-03 17:58:45.988', '2026-06-04 00:14:58.719', NULL, '1 到 n 累加和', 'sum-from-1-to-n', '输入一个正整数 n，计算 1 + 2 + 3 + ... + n 的和。', '一行，一个正整数 n，1 ≤ n ≤ 10^6。', '一行，输出累加的和。', 'Easy', 1000, 128, '可以用循环累加，也可以用等差数列求和公式：n*(n+1)/2，效率更高。', 1, 0, 0);
INSERT INTO `problems` VALUES (24, '2026-06-03 17:58:45.990', '2026-06-04 00:14:58.728', NULL, '阶乘计算', 'factorial', '输入一个正整数 n，计算 n! = 1 × 2 × 3 × ... × n。', '一行，一个正整数 n，0 ≤ n ≤ 20。', '一行，输出 n! 的值。', 'Easy', 1000, 128, '0! = 1，注意 n=0 的边界情况，结果可能很大，需要使用长整型。', 1, 0, 0);
INSERT INTO `problems` VALUES (25, '2026-06-03 17:58:45.991', '2026-06-04 00:14:58.737', NULL, '九九乘法表', 'multiplication-table', '输入一个正整数 n，输出 n 层的九九乘法表，格式为左下三角。', '一行，一个正整数 n，1 ≤ n ≤ 9。', '输出 n 行，第 i 行包含 i 个乘法式子，格式为\"i*j=result\"，用空格分隔。', 'Easy', 1000, 128, '使用两层嵌套循环，外层控制行数，内层控制每行的式子数量。', 1, 0, 0);
INSERT INTO `problems` VALUES (26, '2026-06-03 17:58:45.993', '2026-06-04 00:14:58.747', NULL, '斐波那契数列', 'fibonacci-sequence', '输入一个正整数 n，输出斐波那契数列的第 n 项。斐波那契数列定义：F (1)=1, F (2)=1, F (n)=F (n-1)+F (n-2) (n≥3)。', '一行，一个正整数 n，1 ≤ n ≤ 40。', '一行，输出第 n 项的值。', 'Easy', 1000, 128, '用循环递推比递归效率更高，避免栈溢出。', 1, 0, 0);
INSERT INTO `problems` VALUES (27, '2026-06-03 17:58:45.995', '2026-06-04 00:14:58.756', NULL, '判断素数', 'prime-number-judge', '输入一个大于 1 的正整数，判断它是否为素数（质数）。素数定义：只能被 1 和它本身整除的大于 1 的自然数。', '一行，一个正整数 n，2 ≤ n ≤ 10^6。', '是素数输出\"Prime\"，否则输出\"Not Prime\"。', 'Medium', 1000, 128, '只需判断到√n 即可，不需要判断到 n-1，可以大幅提高效率。', 1, 0, 0);
INSERT INTO `problems` VALUES (28, '2026-06-03 17:58:45.997', '2026-06-04 00:14:58.769', NULL, '输出 n 以内的素数', 'primes-below-n', '输入一个正整数 n，输出所有小于等于 n 的素数，用空格分隔。', '一行，一个正整数 n，2 ≤ n ≤ 1000。', '一行，输出所有≤n 的素数，按从小到大顺序，用空格分隔。', 'Medium', 1000, 128, '可以用埃拉托斯特尼筛法，效率更高。', 1, 0, 0);
INSERT INTO `problems` VALUES (29, '2026-06-03 17:58:45.998', '2026-06-04 00:14:58.778', NULL, '求所有约数', 'find-all-divisors', '输入一个正整数 n，输出它的所有正约数，按从小到大顺序。', '一行，一个正整数 n，1 ≤ n ≤ 10^6。', '一行，输出 n 的所有正约数，用空格分隔。', 'Easy', 1000, 128, '约数是成对出现的，只需循环到√n 即可。', 1, 0, 0);
INSERT INTO `problems` VALUES (30, '2026-06-03 17:58:45.999', '2026-06-04 00:14:58.787', NULL, '反转整数', 'reverse-integer', '输入一个正整数，将它的数位反转后输出。例如输入 123，输出 321。', '一行，一个正整数 n，1 ≤ n ≤ 10^9。', '一行，输出反转后的整数。', 'Easy', 1000, 128, '通过取模和除法操作逐位取出并反转。', 1, 0, 0);
INSERT INTO `problems` VALUES (31, '2026-06-03 17:58:46.001', '2026-06-04 00:14:58.796', NULL, '平方和计算', 'sum-of-squares', '输入一个正整数 n，计算 1² + 2² + 3² + ... + n² 的和。', '一行，一个正整数 n，1 ≤ n ≤ 1000。', '一行，输出平方和的结果。', 'Easy', 1000, 128, '公式：n (n+1)(2n+1)/6，可以直接计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (32, '2026-06-03 17:58:46.004', '2026-06-04 00:14:58.806', NULL, '水仙花数判断', 'narcissistic-number', '输入一个三位数，判断它是否为水仙花数。水仙花数定义：各位数字的立方和等于它本身，例如 153=1³+5³+3³。', '一行，一个三位正整数 n，100 ≤ n ≤ 999。', '是水仙花数输出\"Yes\"，否则输出\"No\"。', 'Easy', 1000, 128, '分别取出百位、十位、个位，计算立方和再比较。', 1, 0, 0);
INSERT INTO `problems` VALUES (33, '2026-06-03 17:58:46.006', '2026-06-04 00:14:58.816', NULL, '所有三位数水仙花数', 'all-narcissistic-numbers', '输出所有的三位水仙花数，用空格分隔。', '无输入。', '一行，所有三位水仙花数，按从小到大顺序，用空格分隔。', 'Easy', 1000, 128, '枚举 100 到 999 的所有数，逐个判断是否为水仙花数。', 1, 0, 0);
INSERT INTO `problems` VALUES (34, '2026-06-03 17:58:46.009', '2026-06-04 00:14:58.826', NULL, '最大公约数', 'greatest-common-divisor', '输入两个正整数 a 和 b，求它们的最大公约数（GCD）。', '一行，包含两个正整数 a 和 b，用空格分隔。', '一行，输出 a 和 b 的最大公约数。', 'Medium', 1000, 128, '推荐使用辗转相除法（欧几里得算法）：gcd (a,b) = gcd (b, a% b)，直到 b 为 0。', 1, 0, 0);
INSERT INTO `problems` VALUES (35, '2026-06-03 17:58:46.011', '2026-06-04 00:14:58.835', NULL, '最小公倍数', 'least-common-multiple', '输入两个正整数 a 和 b，求它们的最小公倍数（LCM）。', '一行，包含两个正整数 a 和 b，用空格分隔。', '一行，输出 a 和 b 的最小公倍数。', 'Medium', 1000, 128, '公式：LCM (a,b) = a × b / GCD (a,b)，先求最大公约数再计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (36, '2026-06-03 17:58:46.013', '2026-06-04 00:14:58.846', NULL, '循环累加直到 0', 'sum-until-zero', '输入若干个整数，直到输入 0 为止，计算所有输入的数（不包括 0）的和。', '若干行，每行一个整数，最后一行是 0。', '一行，输出所有非 0 输入的和。', 'Easy', 1000, 128, '使用 while 循环，当输入为 0 时终止循环。', 1, 0, 0);
INSERT INTO `problems` VALUES (37, '2026-06-03 17:58:46.014', '2026-06-04 00:14:58.855', NULL, '打印菱形', 'print-diamond', '输入一个奇数 n，打印一个边长为 n 的菱形图案，用星号 * 表示。', '一行，一个正奇数 n，3 ≤ n ≤ 19。', '输出 n 行，组成菱形图案。', 'Medium', 1000, 128, '分成上半部分和下半部分分别打印，控制空格和星号的数量。', 1, 0, 0);
INSERT INTO `problems` VALUES (38, '2026-06-03 17:58:46.016', '2026-06-04 00:14:58.865', NULL, '数组元素求和', 'array-sum', '输入 n 个整数，存储到数组中，计算所有元素的和。', '第一行一个正整数 n，表示数组长度。\n第二行 n 个整数，用空格分隔。', '一行，输出数组所有元素的和。', 'Easy', 1000, 128, '遍历数组，逐个累加即可。', 1, 0, 0);
INSERT INTO `problems` VALUES (39, '2026-06-03 17:58:46.018', '2026-06-04 00:14:58.875', NULL, '数组最大值', 'array-max', '输入 n 个整数，输出数组中的最大值。', '第一行一个正整数 n。\n第二行 n 个整数，用空格分隔。', '一行，输出数组中的最大值。', 'Easy', 1000, 128, '初始化最大值为第一个元素，遍历数组逐个比较更新。', 1, 0, 0);
INSERT INTO `problems` VALUES (40, '2026-06-03 17:58:46.020', '2026-06-04 00:14:58.884', NULL, '数组反转', 'array-reverse', '输入 n 个整数，将数组反转后输出。', '第一行一个正整数 n。\n第二行 n 个整数，用空格分隔。', '一行，输出反转后的数组，元素用空格分隔。', 'Easy', 1000, 128, '可以用双指针交换首尾元素，也可以逆序遍历输出。', 1, 0, 0);
INSERT INTO `problems` VALUES (41, '2026-06-03 17:58:46.022', '2026-06-04 00:14:58.893', NULL, '数组升序排序', 'array-sort', '输入 n 个整数，按从小到大的顺序排序后输出。', '第一行一个正整数 n，1 ≤ n ≤ 1000。\n第二行 n 个整数，用空格分隔。', '一行，输出排序后的数组，元素用空格分隔。', 'Medium', 1000, 128, '可以使用冒泡排序、选择排序等基础排序算法。', 1, 0, 0);
INSERT INTO `problems` VALUES (42, '2026-06-03 17:58:46.023', '2026-06-04 00:14:58.903', NULL, '数组去重', 'array-deduplicate', '输入 n 个整数，去除重复元素后，按原顺序输出。', '第一行一个正整数 n。\n第二行 n 个整数，用空格分隔。', '一行，输出去重后的数组，元素用空格分隔。', 'Medium', 1000, 128, '遍历数组，记录已经出现过的元素，只输出第一次出现的元素。', 1, 0, 0);
INSERT INTO `problems` VALUES (43, '2026-06-03 17:58:46.025', '2026-06-04 00:14:58.912', NULL, '数组元素查找', 'array-search', '输入 n 个整数和一个目标数，查找目标数在数组中第一次出现的位置（下标从 0 开始），如果不存在输出 - 1。', '第一行两个正整数 n 和 target。\n第二行 n 个整数，用空格分隔。', '一行，输出目标数第一次出现的下标，不存在则输出 - 1。', 'Easy', 1000, 128, '遍历数组，逐个比较，找到立即返回下标。', 1, 0, 0);
INSERT INTO `problems` VALUES (44, '2026-06-03 17:58:46.030', '2026-06-04 00:14:58.922', NULL, '数组平均值', 'array-average', '输入 n 个整数，计算它们的平均值，保留 2 位小数。', '第一行一个正整数 n。\n第二行 n 个整数，用空格分隔。', '一行，输出平均值，保留 2 位小数。', 'Easy', 1000, 128, '先求和，再除以 n，注意浮点数精度。', 1, 0, 0);
INSERT INTO `problems` VALUES (45, '2026-06-03 17:58:46.031', '2026-06-04 00:14:58.931', NULL, '元素出现次数', 'element-count', '输入 n 个整数和一个目标数，统计目标数在数组中出现的次数。', '第一行两个正整数 n 和 target。\n第二行 n 个整数，用空格分隔。', '一行，输出目标数出现的次数。', 'Easy', 1000, 128, '遍历数组，遇到目标数就计数加 1。', 1, 0, 0);
INSERT INTO `problems` VALUES (46, '2026-06-03 17:58:46.032', '2026-06-04 00:14:58.940', NULL, '数组合并', 'array-merge', '输入两个已经升序排序的数组，将它们合并成一个升序数组后输出。', '第一行两个正整数 n 和 m。\n第二行 n 个升序整数。\n第三行 m 个升序整数。', '一行，输出合并后的升序数组，元素用空格分隔。', 'Medium', 1000, 128, '使用双指针法，同时遍历两个数组，每次取较小的元素。', 1, 0, 0);
INSERT INTO `problems` VALUES (47, '2026-06-03 17:58:46.034', '2026-06-04 00:14:58.949', NULL, '数组右移 k 位', 'array-right-shift', '输入一个长度为 n 的数组，将数组向右循环移动 k 位后输出。例如 [1,2,3,4,5] 右移 2 位变为 [4,5,1,2,3]。', '第一行两个正整数 n 和 k。\n第二行 n 个整数，用空格分隔。', '一行，输出右移后的数组，元素用空格分隔。', 'Medium', 1000, 128, 'k 可以对 n 取模，避免重复移动；可以使用三次反转法实现。', 1, 0, 0);
INSERT INTO `problems` VALUES (48, '2026-06-03 17:58:46.036', '2026-06-04 00:14:58.958', NULL, '字符串长度', 'string-length', '输入一个字符串，输出它的长度（字符个数）。', '一行，一个字符串，不含空格。', '一行，输出字符串的长度。', 'Easy', 1000, 128, '注意不要计算字符串结束符。', 1, 0, 0);
INSERT INTO `problems` VALUES (49, '2026-06-03 17:58:46.037', '2026-06-04 00:14:58.968', NULL, '字符串反转', 'string-reverse', '输入一个字符串，将它反转后输出。', '一行，一个字符串，不含空格。', '一行，输出反转后的字符串。', 'Easy', 1000, 128, '可以用双指针交换首尾字符，也可以逆序遍历输出。', 1, 0, 0);
INSERT INTO `problems` VALUES (50, '2026-06-03 17:58:46.039', '2026-06-04 00:14:58.977', NULL, '字符串拼接', 'string-concat', '输入两个字符串，将它们拼接成一个字符串后输出。', '两行，每行一个字符串，均不含空格。', '一行，输出拼接后的字符串。', 'Easy', 1000, 128, '直接将第二个字符串接在第一个字符串后面即可。', 1, 0, 0);
INSERT INTO `problems` VALUES (51, '2026-06-03 17:58:46.040', '2026-06-04 00:14:58.987', NULL, '回文字符串判断', 'palindrome-judge', '输入一个字符串，判断它是否为回文字符串（正读和反读都一样）。', '一行，一个字符串，不含空格。', '是回文输出\"Yes\"，否则输出\"No\"。', 'Easy', 1000, 128, '用双指针从两端向中间遍历，比较对应位置的字符是否相等。', 1, 0, 0);
INSERT INTO `problems` VALUES (52, '2026-06-03 17:58:46.041', '2026-06-04 00:14:58.997', NULL, '字符类型统计', 'char-type-count', '输入一行字符串，统计其中英文字母、数字、空格和其他字符的个数。', '一行，包含任意字符的字符串（可以包含空格）。', '一行，输出四个整数，分别表示英文字母、数字、空格、其他字符的个数，用空格分隔。', 'Medium', 1000, 128, '遍历每个字符，根据 ASCII 码范围判断类型。', 1, 0, 0);
INSERT INTO `problems` VALUES (53, '2026-06-03 18:41:24.323', '2026-06-04 00:14:59.018', NULL, '分发饼干', 'assign-cookies', '假设你是一位很棒的家长，想要给你的孩子们一些小饼干。但是，每个孩子最多只能给一块饼干。对每个孩子 i，都有一个胃口值 g [i]，这是能让孩子们满足胃口的饼干的最小尺寸；并且每块饼干 j，都有一个尺寸 s [j]。如果 s [j] >= g [i]，我们可以将这个饼干 j 分配给孩子 i，这个孩子会得到满足。你的目标是尽可能满足越多数量的孩子，并输出这个最大数值。', '第一行两个正整数 n 和 m，分别表示孩子数量和饼干数量。\n第二行 n 个整数，表示孩子的胃口数组 g。\n第三行 m 个整数，表示饼干尺寸数组 s。\n数据范围：1 ≤ n, m ≤ 3 * 10^4', '一行，输出最多能满足的孩子数量。', 'Medium', 1000, 128, '贪心策略：将胃口和饼干都排序，用最小的饼干满足最小的胃口，实现资源最优分配。', 1, 0, 0);
INSERT INTO `problems` VALUES (54, '2026-06-03 18:41:24.325', '2026-06-04 00:14:59.047', NULL, '跳跃游戏 I', 'jump-game', '给定一个非负整数数组 nums，你最初位于数组的第一个下标。数组中的每个元素代表你在该位置可以跳跃的最大长度。判断你是否能够到达最后一个下标。', '第一行一个正整数 n，表示数组长度。\n第二行 n 个非负整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 3 * 10^4', '能到达最后一个下标输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '维护当前能到达的最远距离，遍历数组更新最远距离，如果最远距离超过数组末尾则返回成功。', 1, 0, 0);
INSERT INTO `problems` VALUES (55, '2026-06-03 18:41:24.327', '2026-06-04 00:14:59.063', NULL, '跳跃游戏 II', 'jump-game-ii', '给定一个长度为 n 的非负整数数组 nums。你最初位于数组的第一个位置，数组中的每个元素代表你在该位置可以跳跃的最大长度。你的目标是使用最少的跳跃次数到达数组的最后一个位置。假设你总是可以到达数组的最后一个位置。', '第一行一个正整数 n，表示数组长度。\n第二行 n 个非负整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 10^4', '一行，输出最少跳跃次数。', 'Medium', 1000, 128, '贪心策略：每次在可跳范围内选择能跳得最远的位置，实现最少步数。', 1, 0, 0);
INSERT INTO `problems` VALUES (56, '2026-06-03 18:41:24.329', '2026-06-04 00:14:59.079', NULL, '无重叠区间', 'non-overlapping-intervals', '给定一个区间的集合 intervals，其中 intervals [i] = [start_i, end_i]。返回需要移除区间的最小数量，使剩余区间互不重叠。', '第一行一个正整数 n，表示区间数量。\n接下来 n 行，每行两个整数 start 和 end，表示一个区间。\n数据范围：1 ≤ n ≤ 10^5', '一行，输出需要移除的最小区间数量。', 'Medium', 1000, 128, '贪心策略：按区间结束时间排序，优先选择结束早的区间，留出更多空间给后续区间。', 1, 0, 0);
INSERT INTO `problems` VALUES (57, '2026-06-03 18:41:24.330', '2026-06-04 00:14:59.095', NULL, '买卖股票的最佳时机 II', 'best-time-to-buy-and-sell-stock-ii', '给你一个整数数组 prices，其中 prices [i] 表示某支股票第 i 天的价格。在每一天，你可以决定是否购买和 / 或出售股票。你在任何时候最多只能持有一股股票。你也可以先购买，然后在同一天出售。返回你能获得的最大利润。', '第一行一个正整数 n，表示天数。\n第二行 n 个整数，表示股票价格数组。\n数据范围：1 ≤ n ≤ 3 * 10^4', '一行，输出最大利润。', 'Medium', 1000, 128, '贪心策略：只要后一天价格比前一天高，就进行买卖，累加所有上涨的差价。', 1, 0, 0);
INSERT INTO `problems` VALUES (58, '2026-06-03 18:41:24.334', '2026-06-04 00:14:59.111', NULL, '柠檬水找零', 'lemonade-change', '在柠檬水摊上，每一杯柠檬水的售价为 5 美元。顾客排队购买你的产品，按账单 bills 支付的顺序，一次购买一杯。每位顾客只买一杯柠檬水，然后向你付 5 美元、10 美元或 20 美元。你必须给每个顾客正确找零，也就是说净交易是每位顾客向你支付 5 美元。注意，一开始你手头没有任何零钱。给你一个整数数组 bills，其中 bills [i] 是第 i 位顾客付的账。如果你能给每位顾客正确找零，返回 true，否则返回 false。', '第一行一个正整数 n，表示顾客数量。\n第二行 n 个整数，每个为 5、10 或 20。\n数据范围：1 ≤ n ≤ 10^5', '能全部正确找零输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '贪心策略：找零时优先用 10 美元，保留 5 美元（因为 5 美元适用场景更多）。', 1, 0, 0);
INSERT INTO `problems` VALUES (59, '2026-06-03 18:41:24.336', '2026-06-04 00:14:59.138', NULL, '加油站', 'gas-station', '在一条环路上有 n 个加油站，其中第 i 个加油站有汽油 gas [i] 升。你有一辆油箱容量无限的的汽车，从第 i 个加油站开往第 i+1 个加油站需要消耗汽油 cost [i] 升。你从其中的一个加油站出发，开始时油箱为空。给定两个整数数组 gas 和 cost，如果你可以按顺序绕环路行驶一周，则返回出发时加油站的编号，否则返回 -1。如果存在解，则保证它是唯一的。', '第一行一个正整数 n，表示加油站数量。\n第二行 n 个整数，表示 gas 数组。\n第三行 n 个整数，表示 cost 数组。\n数据范围：n == gas.length == cost.length，1 ≤ n ≤ 10^5', '一行，输出出发加油站编号，不存在则输出 - 1。', 'Medium', 1000, 128, '贪心策略：如果总油量大于等于总消耗则一定有解，遍历过程中如果当前累计剩余油量小于 0，则起点设为下一个站。', 1, 0, 0);
INSERT INTO `problems` VALUES (60, '2026-06-03 18:41:24.339', '2026-06-04 00:14:59.153', NULL, '划分字母区间', 'partition-labels', '给你一个字符串 s。我们要把这个字符串划分为尽可能多的片段，同一字母最多出现在一个片段中。返回一个表示每个字符串片段的长度的列表。', '一行，一个仅由小写英文字母组成的字符串 s。\n数据范围：1 ≤ s.length ≤ 500', '一行，输出每个片段的长度，用空格分隔。', 'Medium', 1000, 128, '先记录每个字母最后出现的位置，遍历字符串，当遍历到当前片段所有字母的最后出现位置时，进行分割。', 1, 0, 0);
INSERT INTO `problems` VALUES (61, '2026-06-03 18:41:24.341', '2026-06-04 00:14:59.169', NULL, '爬楼梯', 'climbing-stairs', '假设你正在爬楼梯。需要 n 阶你才能到达楼顶。每次你可以爬 1 或 2 个台阶。你有多少种不同的方法可以爬到楼顶呢？', '一行，一个正整数 n。\n数据范围：1 ≤ n ≤ 45', '一行，输出不同的方法数。', 'Medium', 1000, 128, '动态规划递推公式：dp [i] = dp [i-1] + dp [i-2]，本质是斐波那契数列。', 1, 0, 0);
INSERT INTO `problems` VALUES (62, '2026-06-03 18:41:24.342', '2026-06-04 00:14:59.184', NULL, '不同路径', 'unique-paths', '一个机器人位于一个 m x n 网格的左上角。机器人每次只能向下或者向右移动一步。机器人试图达到网格的右下角。问总共有多少条不同的路径？', '一行，两个正整数 m 和 n，表示网格的行数和列数。\n数据范围：1 ≤ m, n ≤ 100', '一行，输出不同路径的总数。', 'Medium', 1000, 128, '递推公式：dp [i][j] = dp [i-1][j] + dp [i][j-1]，第一行和第一列初始值都为 1。', 1, 0, 0);
INSERT INTO `problems` VALUES (63, '2026-06-03 18:41:24.344', '2026-06-04 00:14:59.199', NULL, '最小路径和', 'minimum-path-sum', '给定一个包含非负整数的 m x n 网格 grid，请你找出一条从左上角到右下角的路径，使得路径上的数字总和为最小。说明：每次只能向下或者向右移动一步。', '第一行两个正整数 m 和 n。\n接下来 m 行，每行 n 个非负整数，表示网格。\n数据范围：1 ≤ m, n ≤ 200', '一行，输出最小路径和。', 'Medium', 1000, 128, '递推公式：dp [i][j] = grid [i][j] + min (dp [i-1][j], dp [i][j-1])，注意边界处理。', 1, 0, 0);
INSERT INTO `problems` VALUES (64, '2026-06-03 18:41:24.346', '2026-06-04 00:14:59.218', NULL, '零钱兑换', 'coin-change', '给你一个整数数组 coins，表示不同面额的硬币；以及一个整数 amount，表示总金额。计算并返回可以凑成总金额所需的最少的硬币个数。如果没有任何一种硬币组合能组成总金额，返回 -1。你可以认为每种硬币的数量是无限的。', '第一行两个正整数 n 和 amount，n 是硬币面额种类数。\n第二行 n 个正整数，表示硬币面额。\n数据范围：1 ≤ n ≤ 12，0 ≤ amount ≤ 10^4', '一行，输出最少硬币数，无法凑出则输出 - 1。', 'Medium', 1000, 128, '完全背包 DP，dp [i] 表示凑成金额 i 所需最少硬币数，递推：dp [i] = min (dp [i], dp [i-coin]+1)。', 1, 0, 0);
INSERT INTO `problems` VALUES (65, '2026-06-03 18:41:24.350', '2026-06-04 00:14:59.231', NULL, '最长上升子序列', 'longest-increasing-subsequence', '给你一个整数数组 nums，找到其中最长严格递增子序列的长度。子序列是由数组派生而来的序列，删除（或不删除）数组中的元素而不改变其余元素的顺序。', '第一行一个正整数 n。\n第二行 n 个整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 2500', '一行，输出最长上升子序列的长度。', 'Medium', 1000, 128, '基础 DP：dp [i] 表示以 nums [i] 结尾的最长上升子序列长度，dp [i] = max (dp [j]+1) for j < i and nums [j] < nums [i]。', 1, 0, 0);
INSERT INTO `problems` VALUES (66, '2026-06-03 18:41:24.352', '2026-06-04 00:14:59.240', NULL, '最长公共子序列', 'longest-common-subsequence', '给定两个字符串 text1 和 text2，返回这两个字符串的最长公共子序列的长度。如果不存在公共子序列，返回 0。一个字符串的子序列是指这样一个新的字符串：它是由原字符串在不改变字符的相对顺序的情况下删除某些字符（也可以不删除任何字符）后组成的新字符串。', '两行，每行一个字符串，分别为 text1 和 text2。\n数据范围：1 ≤ text1.length, text2.length ≤ 1000', '一行，输出最长公共子序列的长度。', 'Medium', 1000, 128, '二维 DP，dp [i][j] 表示 text1 前 i 个字符和 text2 前 j 个字符的最长公共子序列长度。相等时 dp [i][j] = dp [i-1][j-1]+1，不等时取 max (dp [i-1][j], dp [i][j-1])。', 1, 0, 0);
INSERT INTO `problems` VALUES (67, '2026-06-03 18:41:24.354', '2026-06-04 00:14:59.249', NULL, '编辑距离', 'edit-distance', '给你两个单词 word1 和 word2，请你计算出将 word1 转换成 word2 所使用的最少操作数。你可以对一个单词进行如下三种操作：插入一个字符、删除一个字符、替换一个字符。', '两行，每行一个字符串，分别为 word1 和 word2。\n数据范围：0 ≤ word1.length, word2.length ≤ 500', '一行，输出最少操作数。', 'Hard', 1000, 128, '经典 DP 问题，dp [i][j] 表示 word1 前 i 个字符转成 word2 前 j 个字符的最少操作数。字符相等时 dp [i][j] = dp [i-1][j-1]，不等时取替换、删除、插入三种操作的最小值 + 1。', 1, 0, 0);
INSERT INTO `problems` VALUES (68, '2026-06-03 18:41:24.356', '2026-06-04 00:14:59.258', NULL, '0-1 背包问题', '01-knapsack', '有 n 件物品和一个最多能承受重量为 w 的背包。第 i 件物品的重量是 weight [i]，价值是 value [i]。每件物品只能用一次，求解将哪些物品装入背包里物品价值总和最大。', '第一行两个正整数 n 和 w，分别是物品数和背包承重。\n接下来 n 行，每行两个整数 weight [i] 和 value [i]，表示第 i 件物品的重量和价值。\n数据范围：1 ≤ n ≤ 1000，1 ≤ w ≤ 1000', '一行，输出最大价值总和。', 'Medium', 1000, 128, '0-1 背包标准 DP，dp [j] 表示容量为 j 的背包能装的最大价值，逆序遍历背包容量避免重复选取物品。', 1, 0, 0);
INSERT INTO `problems` VALUES (69, '2026-06-03 18:41:24.358', '2026-06-04 00:14:59.266', NULL, '分割等和子集', 'partition-equal-subset-sum', '给你一个只包含正整数的非空数组 nums。请你判断是否可以将这个数组分割成两个子集，使得两个子集的元素和相等。', '第一行一个正整数 n。\n第二行 n 个正整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 200，1 ≤ nums [i] ≤ 100', '可以分割输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '转化为 0-1 背包问题：是否能选出若干元素，和为总和的一半。总和为奇数直接返回 No。', 1, 0, 0);
INSERT INTO `problems` VALUES (70, '2026-06-03 18:41:24.360', '2026-06-04 00:14:59.274', NULL, '最大子数组和', 'maximum-subarray', '给你一个整数数组 nums，请你找出一个具有最大和的连续子数组（子数组最少包含一个元素），返回其最大和。', '第一行一个正整数 n。\n第二行 n 个整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 10^5，-10^4 ≤ nums [i] ≤ 10^4', '一行，输出最大子数组和。', 'Medium', 1000, 128, 'Kadane 算法：dp [i] = max (nums [i], dp [i-1]+nums [i])，维护当前最大子数组和。', 1, 0, 0);
INSERT INTO `problems` VALUES (71, '2026-06-03 18:41:24.362', '2026-06-04 00:14:59.284', NULL, '打家劫舍', 'house-robber', '你是一个专业的小偷，计划偷窃沿街的房屋。每间房内都藏有一定的现金，影响你偷窃的唯一制约因素就是相邻的房屋装有相互连通的防盗系统，如果两间相邻的房屋在同一晚上被小偷闯入，系统会自动报警。给定一个代表每个房屋存放金额的非负整数数组，计算你不触动警报装置的情况下，一夜之内能够偷窃到的最高金额。', '第一行一个正整数 n。\n第二行 n 个非负整数，表示每个房屋的金额。\n数据范围：1 ≤ n ≤ 100', '一行，输出能偷窃的最高金额。', 'Medium', 1000, 128, '递推公式：dp [i] = max (dp [i-1], dp [i-2]+nums [i])，即第 i 间房偷或不偷两种选择取最大值。', 1, 0, 0);
INSERT INTO `problems` VALUES (72, '2026-06-03 18:41:24.363', '2026-06-04 00:14:59.293', NULL, '打家劫舍 II', 'house-robber-ii', '你是一个专业的小偷，计划偷窃沿街的房屋，每间房内都藏有一定的现金。这个地方所有的房屋都围成一圈，这意味着第一个房屋和最后一个房屋是紧挨着的。同时，相邻的房屋装有相互连通的防盗系统，如果两间相邻的房屋在同一晚上被小偷闯入，系统会自动报警。给定一个代表每个房屋存放金额的非负整数数组，计算你在不触动警报装置的情况下，今晚能够偷窃到的最高金额。', '第一行一个正整数 n。\n第二行 n 个非负整数，表示每个房屋的金额。\n数据范围：1 ≤ n ≤ 100', '一行，输出能偷窃的最高金额。', 'Medium', 1000, 128, '拆分成两个子问题：不偷第一个房屋的最大值，和不偷最后一个房屋的最大值，取两者较大值。', 1, 0, 0);
INSERT INTO `problems` VALUES (73, '2026-06-03 18:41:24.366', '2026-06-04 00:14:59.302', NULL, '单词拆分', 'word-break', '给你一个字符串 s 和一个字符串列表 wordDict 作为字典。请你判断是否可以利用字典中出现的单词拼接出 s。注意：不要求字典中出现的单词全部都使用，并且字典中的单词可以重复使用。', '第一行一个字符串 s。\n第二行一个正整数 n，表示字典单词数量。\n接下来 n 行，每行一个字符串，表示字典中的单词。\n数据范围：1 ≤ s.length ≤ 300，1 ≤ n ≤ 1000', '可以拼接输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, 'dp [i] 表示字符串前 i 个字符是否可以被拼接。dp [i] = dp [j] && (s [j..i-1] in wordDict) for j < i。', 1, 0, 0);
INSERT INTO `problems` VALUES (74, '2026-06-03 18:41:24.367', '2026-06-04 00:14:59.311', NULL, '正则表达式匹配', 'regular-expression-matching', '给你一个字符串 s 和一个字符规律 p，请你来实现一个支持 \'.\' 和 \'*\' 的正则表达式匹配。\'.\' 匹配任意单个字符，\'*\' 匹配零个或多个前面的那一个元素。所谓匹配，是要涵盖整个字符串 s 的，而不是部分字符串。', '两行，第一行字符串 s，第二行模式 p。\n数据范围：0 ≤ s.length, p.length ≤ 20', '匹配成功输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '二维 DP，dp [i][j] 表示 s 前 i 个字符和 p 前 j 个字符是否匹配。分普通字符、.、*三种情况处理。', 1, 0, 0);
INSERT INTO `problems` VALUES (75, '2026-06-03 18:41:24.371', '2026-06-04 00:14:59.323', NULL, '岛屿数量', 'number-of-islands', '给你一个由 \'1\'（陆地）和 \'0\'（水）组成的的二维网格，请你计算网格中岛屿的数量。岛屿总是被水包围，并且每座岛屿只能由水平方向和 / 或竖直方向上相邻的陆地连接形成。此外，你可以假设该网格的四条边均被水包围。', '第一行两个正整数 m 和 n，表示网格行列数。\n接下来 m 行，每行 n 个字符，为 \'0\' 或 \'1\'。\n数据范围：1 ≤ m, n ≤ 300', '一行，输出岛屿数量。', 'Medium', 1000, 128, '遍历网格，遇到陆地则 DFS/BFS 标记所有连通的陆地，每完成一次遍历岛屿数 + 1。', 1, 0, 0);
INSERT INTO `problems` VALUES (76, '2026-06-03 18:41:24.373', '2026-06-04 00:14:59.333', NULL, '岛屿的最大面积', 'max-area-of-island', '给你一个大小为 m x n 的二进制矩阵 grid。岛屿是由一些相邻的 1 (代表土地) 构成的组合，这里的「相邻」要求两个 1 必须在水平或者竖直方向上相邻。你可以假设 grid 的四个边缘都被 0（代表水）包围着。返回给定的网格中最大的岛屿面积。如果没有岛屿，则返回面积为 0。', '第一行两个正整数 m 和 n。\n接下来 m 行，每行 n 个整数 0 或 1。\n数据范围：1 ≤ m, n ≤ 50', '一行，输出最大岛屿面积。', 'Medium', 1000, 128, 'DFS/BFS 遍历每个连通分量，计算面积并记录最大值。', 1, 0, 0);
INSERT INTO `problems` VALUES (77, '2026-06-03 18:41:24.376', '2026-06-04 00:14:59.343', NULL, '课程表', 'course-schedule', '你这个学期必须选修 numCourses 门课程，记为 0 到 numCourses - 1。在选修某些课程之前需要一些先修课程。先修课程按数组 prerequisites 给出，其中 prerequisites [i] = [ai, bi]，表示如果要学习课程 ai 则必须先学习课程 bi。请你判断是否可能完成所有课程的学习？', '第一行两个正整数 numCourses 和 m，m 是先修关系数量。\n接下来 m 行，每行两个整数 ai 和 bi，表示先修关系。\n数据范围：1 ≤ numCourses ≤ 2000，0 ≤ m ≤ 5000', '可以完成所有课程输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '拓扑排序：构建有向图，计算入度，BFS 遍历入度为 0 的节点，最后判断遍历节点数是否等于课程数。', 1, 0, 0);
INSERT INTO `problems` VALUES (78, '2026-06-03 18:41:24.379', '2026-06-04 00:14:59.353', NULL, '课程表 II', 'course-schedule-ii', '现在你总共有 numCourses 门课需要选，记为 0 到 numCourses - 1。给你一个数组 prerequisites，其中 prerequisites[i] = [ai, bi]，表示在选修课程 ai 前必须先选修 bi。请输出为了完成所有课程可以安排的字典序最小学习顺序。如果不可能完成所有课程，输出 -1。', '第一行两个正整数 numCourses 和 m。\n接下来 m 行，每行两个整数 ai 和 bi。\n数据范围：1 ≤ numCourses ≤ 2000，0 ≤ m ≤ 5000', '一行，输出字典序最小的学习顺序，用空格分隔；如果无法完成所有课程，输出 -1。', 'Medium', 1000, 128, '拓扑排序过程中记录节点顺序，即为合法的学习顺序。', 1, 0, 0);
INSERT INTO `problems` VALUES (79, '2026-06-03 18:41:24.384', '2026-06-04 00:14:59.362', NULL, '网络延迟时间', 'network-delay-time', '有 n 个网络节点，标记为 1 到 n。给你一个列表 times，表示信号经过有向边的传递时间。times [i] = (ui, vi, wi)，其中 ui 是源节点，vi 是目标节点，wi 是一个信号从源节点传递到目标节点的时间。现在，从某个节点 k 发出一个信号。需要多久才能使所有节点都收到信号？如果不能使所有节点收到信号，返回 -1。', '第一行三个正整数 n、m、k，n 是节点数，m 是边数，k 是起点。\n接下来 m 行，每行三个整数 ui、vi、wi。\n数据范围：1 ≤ k ≤ n ≤ 100，1 ≤ m ≤ 6000', '一行，输出所有节点收到信号的最短时间，无法全部收到输出 - 1。', 'Medium', 1000, 128, 'Dijkstra 算法求起点到所有节点的最短路径，取最大值即为答案；若有节点不可达返回 - 1。', 1, 0, 0);
INSERT INTO `problems` VALUES (80, '2026-06-03 18:41:24.386', '2026-06-04 00:14:59.373', NULL, '二分图判定', 'is-graph-bipartite', '存在一个无向图，图中有 n 个节点。其中每个节点都有一个介于 0 到 n - 1 之间的唯一编号。给你一个二维数组 graph，其中 graph [u] 是一个节点数组，由节点 u 的邻接节点组成。如果图是二分图，返回 true；否则，返回 false。二分图定义：如果能将一个图的节点集合分割成两个独立的子集 A 和 B，并使图中的每一条边的两个节点一个来自 A 集合，一个来自 B 集合，就将这个图称为二分图。', '第一行一个正整数 n，表示节点数。\n接下来 n 行，每行若干个整数，表示对应节点的邻接节点。\n数据范围：1 ≤ n ≤ 100', '是二分图输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '染色法：用两种颜色标记节点，相邻节点颜色必须不同，DFS/BFS 遍历过程中如果发现冲突则不是二分图。', 1, 0, 0);
INSERT INTO `problems` VALUES (81, '2026-06-03 18:41:24.388', '2026-06-04 00:14:59.383', NULL, '二分查找', 'binary-search', '给定一个 n 个元素有序的（升序）整型数组 nums 和一个目标值 target，写一个函数搜索 nums 中的 target，如果目标值存在返回下标，否则返回 -1。', '第一行两个正整数 n 和 target。\n第二行 n 个升序整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 10^4，数组元素不重复。', '一行，输出目标值的下标，不存在则输出 - 1。', 'Medium', 1000, 128, '标准二分查找模板，注意边界条件：left <= right，mid = left + (right - left)/2 防止溢出。', 1, 0, 0);
INSERT INTO `problems` VALUES (82, '2026-06-03 18:41:24.390', '2026-06-04 00:14:59.392', NULL, '搜索插入位置', 'search-insert-position', '给定一个排序数组和一个目标值，在数组中找到目标值，并返回其索引。如果目标值不存在于数组中，返回它将会被按顺序插入的位置。请必须使用时间复杂度为 O (log n) 的算法。', '第一行两个正整数 n 和 target。\n第二行 n 个升序整数，表示数组。\n数据范围：1 ≤ n ≤ 10^4', '一行，输出目标值的索引或插入位置。', 'Medium', 1000, 128, '二分查找变种，最终 left 的位置即为插入位置。', 1, 0, 0);
INSERT INTO `problems` VALUES (83, '2026-06-03 18:41:24.392', '2026-06-04 00:14:59.405', NULL, '在排序数组中查找元素的第一个和最后一个位置', 'find-first-and-last-position-of-element-in-sorted-array', '给你一个按照非递减顺序排列的整数数组 nums，和一个目标值 target。请你找出给定目标值在数组中的开始位置和结束位置。如果数组中不存在目标值 target，返回 [-1, -1]。你必须设计并实现时间复杂度为 O (log n) 的算法解决此问题。', '第一行两个正整数 n 和 target。\n第二行 n 个非递减整数，表示数组。\n数据范围：0 ≤ n ≤ 10^5', '一行，输出两个整数，分别为开始位置和结束位置，不存在则输出 -1 -1。', 'Medium', 1000, 128, '两次二分查找：一次找左边界，一次找右边界。', 1, 0, 0);
INSERT INTO `problems` VALUES (84, '2026-06-03 18:41:24.394', '2026-06-04 00:14:59.415', NULL, '三数之和', '3sum', '给你一个整数数组 nums，判断是否存在三元组 [nums [i], nums [j], nums [k]] 满足 i != j、i != k 且 j != k，同时还满足 nums [i] + nums [j] + nums [k] == 0。请你返回所有和为 0 且不重复的三元组的数量。', '第一行一个正整数 n。\n第二行 n 个整数，表示数组 nums。\n数据范围：3 ≤ n ≤ 3000', '一行，输出不重复的三元组数量。', 'Medium', 1000, 128, '排序后固定第一个数，双指针找另外两个数，注意去重处理。', 1, 0, 0);
INSERT INTO `problems` VALUES (85, '2026-06-03 18:41:24.396', '2026-06-04 00:14:59.424', NULL, '盛最多水的容器', 'container-with-most-water', '给定一个长度为 n 的整数数组 height。有 n 条垂线，第 i 条线的两个端点是 (i, 0) 和 (i, height [i])。找出其中的两条线，使得它们与 x 轴共同构成的容器可以容纳最多的水。返回容器可以储存的最大水量。', '第一行一个正整数 n。\n第二行 n 个非负整数，表示 height 数组。\n数据范围：n ≥ 2', '一行，输出最大盛水量。', 'Medium', 1000, 128, '双指针分别指向左右两端，每次移动高度较小的指针，计算面积并更新最大值。', 1, 0, 0);
INSERT INTO `problems` VALUES (86, '2026-06-03 18:41:24.398', '2026-06-04 00:14:59.433', NULL, '移动零', 'move-zeroes', '给定一个数组 nums，编写一个函数将所有 0 移动到数组的末尾，同时保持非零元素的相对顺序。请注意，必须在不复制数组的情况下原地对数组进行操作。', '第一行一个正整数 n。\n第二行 n 个整数，表示数组 nums。', '一行，输出处理后的数组，元素用空格分隔。', 'Medium', 1000, 128, '双指针：慢指针指向非零元素应该放置的位置，快指针遍历数组，遇到非零则交换到慢指针位置。', 1, 0, 0);
INSERT INTO `problems` VALUES (87, '2026-06-03 18:41:24.400', '2026-06-04 00:14:59.446', NULL, '全排列', 'permutations', '给定一个不含重复数字的数组 nums，返回其所有可能的全排列。输出全排列的总数。', '第一行一个正整数 n。\n第二行 n 个不重复整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 6', '一行，输出全排列的总数。', 'Medium', 1000, 128, '回溯法：递归生成所有排列，用 used 数组标记已使用的元素。', 1, 0, 0);
INSERT INTO `problems` VALUES (88, '2026-06-03 18:41:24.402', '2026-06-04 00:14:59.455', NULL, '子集', 'subsets', '给你一个整数数组 nums，数组中的元素互不相同。返回该数组所有可能的子集（幂集）。输出子集的总数。', '第一行一个非负整数 n。\n第二行 n 个不重复整数；当 n=0 时第二行可以省略。\n数据范围：0 ≤ n ≤ 10', '一行，输出子集的总数。', 'Medium', 1000, 128, '每个元素有选或不选两种状态，总数为 2^n；也可以用回溯法生成所有子集。', 1, 0, 0);
INSERT INTO `problems` VALUES (89, '2026-06-03 18:41:24.422', '2026-06-04 00:14:59.464', NULL, '组合总和', 'combination-sum', '给你一个无重复元素的整数数组 candidates 和一个目标整数 target，找出 candidates 中可以使数字和为目标数 target 的所有不同组合，输出组合的总数。candidates 中的同一个数字可以无限制重复被选取。', '第一行两个正整数 n 和 target。\n第二行 n 个不同的正整数。\n数据范围：1 ≤ n ≤ 30，1 ≤ target ≤ 500', '一行，输出符合条件的组合总数。', 'Medium', 1000, 128, '回溯法，按顺序选择元素避免重复组合，总和超过 target 时剪枝。', 1, 0, 0);
INSERT INTO `problems` VALUES (90, '2026-06-03 18:41:24.428', '2026-06-04 00:14:59.474', NULL, '括号生成', 'generate-parentheses', '数字 n 代表生成括号的对数，请你设计一个函数，用于能够生成所有可能的并且有效的括号组合。输出有效括号组合的总数。', '一行，一个正整数 n。\n数据范围：1 ≤ n ≤ 8', '一行，输出有效括号组合的总数。', 'Medium', 1000, 128, '回溯法：左括号数量不超过 n，右括号数量不超过左括号数量，最终长度为 2n 时为有效组合。', 1, 0, 0);
INSERT INTO `problems` VALUES (91, '2026-06-03 18:41:24.430', '2026-06-04 00:14:59.483', NULL, 'N 皇后', 'n-queens', '按照国际象棋的规则，皇后可以攻击与之处在同一行或同一列或同一斜线上的棋子。n 皇后问题研究的是如何将 n 个皇后放置在 n×n 的棋盘上，并且使皇后彼此之间不能相互攻击。给你一个整数 n，返回所有不同的 n 皇后问题的解决方案的数量。', '一行，一个正整数 n。\n数据范围：1 ≤ n ≤ 9', '一行，输出不同解决方案的数量。', 'Hard', 1000, 128, '回溯法，按行放置皇后，用三个集合标记列、主对角线、副对角线是否已被占用。', 1, 0, 0);
INSERT INTO `problems` VALUES (92, '2026-06-03 18:41:24.432', '2026-06-04 00:14:59.493', NULL, '单词搜索', 'word-search', '给定一个 m x n 二维字符网格 board 和一个字符串单词 word。如果 word 存在于网格中，返回 true；否则，返回 false。单词必须按照字母顺序，通过相邻的单元格内的字母构成，其中 “相邻” 单元格是那些水平相邻或垂直相邻的单元格。同一个单元格内的字母不允许被重复使用。', '第一行两个正整数 m 和 n。\n接下来 m 行，每行 n 个大写字母。\n最后一行一个字符串 word。\n数据范围：1 ≤ m, n ≤ 6，1 ≤ word.length ≤ 15', '存在输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, 'DFS 回溯，从每个匹配首字母的位置开始搜索，四个方向探索，标记已访问位置，回溯时恢复。', 1, 0, 0);
INSERT INTO `problems` VALUES (93, '2026-06-03 18:41:24.434', '2026-06-04 00:14:59.502', NULL, '只出现一次的数字', 'single-number', '给你一个非空整数数组 nums，除了某个元素只出现一次以外，其余每个元素均出现两次。找出那个只出现了一次的元素。你必须设计并实现线性时间复杂度的算法来解决此问题，且该算法只使用常量额外空间。', '第一行一个正整数 n。\n第二行 n 个整数。', '一行，输出只出现一次的数字。', 'Medium', 1000, 128, '异或运算性质：a^a=0，a^0=a，所有元素异或结果即为只出现一次的数。', 1, 0, 0);
INSERT INTO `problems` VALUES (94, '2026-06-03 18:41:24.436', '2026-06-04 00:14:59.512', NULL, 'Pow (x, n)', 'powx-n', '实现 pow (x, n)，即计算 x 的整数 n 次幂函数（即，x^n）。', '一行，一个浮点数 x 和一个整数 n。\n数据范围：-100.0 < x < 100.0，-2^31 ≤ n ≤ 2^31-1', '一行，输出计算结果，保留 5 位小数。', 'Medium', 1000, 128, '快速幂算法（二进制拆分），时间复杂度 O (logn)，注意 n 为负数的情况。', 1, 0, 0);
INSERT INTO `problems` VALUES (95, '2026-06-03 18:41:24.437', '2026-06-04 00:14:59.521', NULL, '多数元素', 'majority-element', '给定一个大小为 n 的数组 nums，返回其中的多数元素。多数元素是指在数组中出现次数大于 ⌊n/2⌋ 的元素。你可以假设数组是非空的，并且给定的数组总是存在多数元素。', '第一行一个正整数 n。\n第二行 n 个整数。', '一行，输出多数元素。', 'Medium', 1000, 128, '摩尔投票法：候选数 + 计数，相同计数 + 1，不同计数 - 1，计数为 0 时更换候选数，最终候选数即为多数元素。', 1, 0, 0);
INSERT INTO `problems` VALUES (96, '2026-06-03 18:41:24.439', '2026-06-04 00:14:59.530', NULL, '约瑟夫环', 'josephus-problem', '0,1,・・・,n-1 这 n 个数字排成一个圆圈，从数字 0 开始，每次从这个圆圈里删除第 m 个数字（删除后从下一个数字开始计数）。求出这个圆圈里剩下的最后一个数字。', '一行，两个正整数 n 和 m。\n数据范围：1 ≤ n ≤ 10^5，1 ≤ m ≤ 10^6', '一行，输出最后剩下的数字。', 'Medium', 1000, 128, '约瑟夫环递推公式：f (n) = (f (n-1) + m) % n，f (1)=0。', 1, 0, 0);
INSERT INTO `problems` VALUES (97, '2026-06-03 19:49:41.527', '2026-06-04 00:14:59.539', NULL, '并查集：朋友圈', 'friend-circles', '班上有 N 名学生。其中有些人是朋友，有些则不是。他们的友谊具有是传递性。如果已知 A 是 B 的朋友，B 是 C 的朋友，那么我们可以认为 A 也是 C 的朋友。所谓的朋友圈，是指所有朋友的集合。给定一个 N * N 的矩阵 M，表示班级中学生之间的朋友关系。如果 M [i][j] = 1，表示已知第 i 个和 j 个学生互为朋友关系，否则为不知道。你必须输出所有学生中的已知的朋友圈总数。', '第一行一个正整数 N，表示学生人数。\n接下来 N 行，每行 N 个整数 0 或 1，表示友谊矩阵 M。\n数据范围：1 ≤ N ≤ 200', '一行，输出朋友圈的总数。', 'Hard', 1000, 128, '标准并查集应用：每个学生初始为独立集合，遍历友谊矩阵，是朋友则合并两个集合，最终统计集合数量。', 1, 0, 0);
INSERT INTO `problems` VALUES (98, '2026-06-03 19:49:41.532', '2026-06-04 00:14:59.549', NULL, '线段树：区间求和与更新', 'segment-tree-range-sum', '给定一个整数数组 nums，实现两种操作：1. 更新数组中某个位置的值；2. 返回数组区间 [left, right] 的元素总和（包含 left 和 right）。', '第一行两个正整数 n 和 q，n 是数组长度，q 是操作次数。\n第二行 n 个整数，表示初始数组 nums。\n接下来 q 行，每行第一个数为操作类型：\n- 1 index val：将 nums [index] 更新为 val\n- 2 left right：查询区间 [left, right] 的和\n数据范围：1 ≤ n, q ≤ 3 * 10^4', '对于每个查询操作，输出一行对应的区间和。', 'Hard', 1000, 128, '使用线段树实现，支持 O (logn) 时间复杂度的单点更新和区间查询，注意数组下标从 0 开始还是 1 开始。', 1, 0, 0);
INSERT INTO `problems` VALUES (99, '2026-06-03 19:49:41.534', '2026-06-04 00:14:59.559', NULL, '树状数组：逆序对计数', 'count-inversions', '在数组中的两个数字，如果前面一个数字大于后面的数字，则这两个数字组成一个逆序对。输入一个数组，求出这个数组中的逆序对的总数。', '第一行一个正整数 n，表示数组长度。\n第二行 n 个整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 5 * 10^4', '一行，输出逆序对的总数。', 'Hard', 1000, 128, '离散化 + 树状数组：将数组值映射到排名，从后往前遍历数组，查询当前值之前有多少个更小的数，累加即为逆序对总数，时间复杂度 O (nlogn)。', 1, 0, 0);
INSERT INTO `problems` VALUES (100, '2026-06-03 19:49:41.536', '2026-06-04 00:14:59.568', NULL, '字典树 Trie：前缀统计', 'trie-prefix-count', '实现一个 Trie (前缀树)，包含 insert 和 query 两个操作。insert 用于插入一个字符串，query 用于查询有多少个插入的字符串以给定前缀开头。', '第一行一个正整数 q，表示操作次数。\n接下来 q 行，每行两个值：操作类型和字符串。\n- 1 s：插入字符串 s\n- 2 s：查询以 s 为前缀的字符串数量\n数据范围：1 ≤ q ≤ 10^5，字符串仅含小写字母，总长度不超过 10^6', '对于每个查询操作，输出一行对应的数量。', 'Hard', 1000, 128, 'Trie 树每个节点记录经过该节点的字符串数量，插入时沿途计数 + 1，查询时返回最终节点的计数值。', 1, 0, 0);
INSERT INTO `problems` VALUES (101, '2026-06-03 19:49:41.543', '2026-06-04 00:14:59.578', NULL, '单调栈：柱状图中最大矩形', 'largest-rectangle-in-histogram', '给定 n 个非负整数，用来表示柱状图中各个柱子的高度。每个柱子彼此相邻，且宽度为 1。求在该柱状图中，能够勾勒出来的矩形的最大面积。', '第一行一个正整数 n。\n第二行 n 个非负整数，表示柱子高度。\n数据范围：1 ≤ n ≤ 10^5', '一行，输出最大矩形面积。', 'Hard', 1000, 128, '单调递增栈：栈中保存下标，对应高度递增。遇到比栈顶小的元素时，弹出栈顶计算以该高度为高的矩形宽度，更新最大面积。', 1, 0, 0);
INSERT INTO `problems` VALUES (102, '2026-06-03 19:49:41.544', '2026-06-04 00:14:59.588', NULL, '单调队列：滑动窗口最大值', 'sliding-window-maximum', '给你一个整数数组 nums，有一个大小为 k 的滑动窗口从数组的最左侧移动到数组的最右侧。你只可以看到在滑动窗口内的 k 个数字。滑动窗口每次只向右移动一位。返回滑动窗口中的最大值。', '第一行两个正整数 n 和 k。\n第二行 n 个整数，表示数组 nums。\n数据范围：1 ≤ n ≤ 10^5，1 ≤ k ≤ n', '一行，输出每个滑动窗口的最大值，用空格分隔。', 'Hard', 1000, 128, '单调递减队列：队列中保存下标，对应值递减。每次新元素入队前弹出所有比它小的队尾元素，队首即为当前窗口最大值，同时移除超出窗口范围的队首。', 1, 0, 0);
INSERT INTO `problems` VALUES (103, '2026-06-03 19:49:41.546', '2026-06-04 00:14:59.598', NULL, 'LRU 缓存机制', 'lru-cache', '请你设计并实现一个满足 LRU (最近最少使用) 缓存约束的数据结构。实现 LRUCache 类：LRUCache (int capacity) 以正整数作为容量 capacity 初始化 LRU 缓存；int get (int key) 如果关键字 key 存在于缓存中，则返回关键字的值，否则返回 -1；void put (int key, int value) 如果关键字 key 已经存在，则变更其数据值 value；如果不存在，则向缓存中插入该组 key-value。如果插入操作导致关键字数量超过 capacity，则应该逐出最久未使用的关键字。函数 get 和 put 必须以 O (1) 的平均时间复杂度运行。', '第一行两个正整数 capacity 和 q，分别是缓存容量和操作次数。\n接下来 q 行，每行操作：\n- 1 key：get 操作，返回 key 对应的值\n- 2 key value：put 操作，插入或更新键值对\n数据范围：1 ≤ capacity ≤ 3000，1 ≤ q ≤ 10^5', '对于每个 get 操作，输出一行对应的值，不存在则输出 - 1。', 'Hard', 1000, 128, '哈希表 + 双向链表：哈希表存储 key 到链表节点的映射，双向链表按访问顺序排列，头部是最近使用，尾部是最久未使用，get 和 put 都调整节点位置，超出容量时删除尾部节点。', 1, 0, 0);
INSERT INTO `problems` VALUES (104, '2026-06-03 19:49:41.547', '2026-06-04 00:14:59.609', NULL, '二叉树的最近公共祖先', 'lowest-common-ancestor', '给定一个二叉树，找到该树中两个指定节点的最近公共祖先。最近公共祖先的定义为：对于有根树 T 的两个节点 p、q，最近公共祖先表示为一个节点 x，满足 x 是 p、q 的祖先且 x 的深度尽可能大（一个节点也可以是它自己的祖先）。', '第一行一个正整数 n，表示二叉树节点数，节点编号 1~n。\n第二行 n 个整数，表示二叉树的层序遍历，-1 表示空节点。\n第三行两个整数 p 和 q，表示要查询的两个节点。\n数据范围：2 ≤ n ≤ 10^5', '一行，输出最近公共祖先的节点编号。', 'Hard', 1000, 128, '递归法：如果当前节点是 p 或 q 则返回当前节点；左右子树分别递归，左右都有返回值则当前节点是 LCA，只有一侧有返回值则返回该侧结果。', 1, 0, 0);
INSERT INTO `problems` VALUES (105, '2026-06-03 19:49:41.549', '2026-06-04 00:14:59.620', NULL, '欧拉筛素数', 'sieve-of-eratosthenes', '给定一个正整数 n，统计所有小于等于 n 的素数的个数。', '一行，一个正整数 n。\n数据范围：0 ≤ n ≤ 5 * 10^6', '一行，输出小于等于 n 的素数个数。', 'Hard', 1000, 128, '使用欧拉筛（线性筛），时间复杂度 O (n)，每个合数只会被它的最小质因子筛一次，比埃氏筛效率更高。', 1, 0, 0);
INSERT INTO `problems` VALUES (106, '2026-06-03 19:49:41.550', '2026-06-04 00:14:59.629', NULL, '快速幂取模', 'fast-power-mod', '计算 a^b mod p 的值，其中 a、b、p 都是正整数。', '一行，三个正整数 a、b、p。\n数据范围：1 ≤ a, b, p ≤ 10^9', '一行，输出 (a^b) mod p 的结果。', 'Hard', 1000, 128, '二进制快速幂：将指数 b 拆分为二进制，每次底数平方，遇到二进制位为 1 则乘到结果中，全程取模防止溢出。', 1, 0, 0);
INSERT INTO `problems` VALUES (107, '2026-06-03 19:49:41.552', '2026-06-04 00:14:59.640', NULL, '乘法逆元', 'modular-inverse', '给定两个正整数 a 和 p，p 是质数，求 a 在模 p 意义下的乘法逆元 x，满足 (a * x) mod p = 1。如果不存在逆元输出 - 1。', '一行，两个正整数 a 和 p，p 是质数。\n数据范围：1 ≤ a < p ≤ 10^9', '一行，输出 a 的模 p 逆元，不存在则输出 - 1。', 'Hard', 1000, 128, '费马小定理：p 是质数时，a^(p-2) mod p 即为 a 的逆元，用快速幂计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (108, '2026-06-03 19:49:41.553', '2026-06-04 00:14:59.649', NULL, '扩展欧几里得算法', 'extended-gcd', '给定两个正整数 a 和 b，求整数 x 和 y，使得 a*x + b*y = gcd (a, b)。输出 gcd (a,b) 以及任意一组满足条件的 x 和 y。', '一行，两个正整数 a 和 b。\n数据范围：1 ≤ a, b ≤ 10^9', '一行，输出三个整数：gcd(a,b)、x、y，用空格分隔。为避免多解导致判题歧义，要求输出扩展欧几里得递归得到的一组系数；建议使用标准递归：exgcd(b, a%b) 回溯得到 x=y1, y=x1-(a/b)*y1。', 'Hard', 1000, 128, '扩展欧几里得算法：在欧几里得算法求 gcd 的过程中，递归回溯计算 x 和 y 的值。', 1, 0, 0);
INSERT INTO `problems` VALUES (109, '2026-06-03 19:49:41.555', '2026-06-04 00:14:59.658', NULL, '中国剩余定理', 'chinese-remainder-theorem', '求解同余方程组：x ≡ a1 mod m1，x ≡ a2 mod m2，...，x ≡ an mod mn，其中 m1, m2, ..., mn 两两互质。输出最小的非负整数解 x。', '第一行一个正整数 n，表示方程个数。\n接下来 n 行，每行两个整数 ai 和 mi。\n数据范围：1 ≤ n ≤ 10，1 ≤ mi ≤ 1000，mi 两两互质。', '一行，输出最小的非负整数解 x。', 'Hard', 1000, 128, '中国剩余定理：计算 M = 乘积 mi，Mi=M/mi，求 Mi 在模 mi 下的逆元 ti，x=sum (ai*Mi*ti) mod M。', 1, 0, 0);
INSERT INTO `problems` VALUES (110, '2026-06-03 19:49:41.557', '2026-06-04 00:14:59.667', NULL, '欧拉函数', 'euler-totient-function', '给定正整数 n，计算欧拉函数 φ(n) 的值。欧拉函数 φ(n) 表示小于等于 n 且与 n 互质的正整数的个数。', '一行，一个正整数 n。\n数据范围：1 ≤ n ≤ 10^6', '一行，输出 φ(n) 的值。', 'Hard', 1000, 128, 'φ(n) = n * 乘积 (1 - 1/p)，其中 p 是 n 的所有不同质因子。先分解 n 的质因数，再按公式计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (111, '2026-06-03 19:49:41.558', '2026-06-04 00:14:59.675', NULL, '质因数分解', 'prime-factorization', '给定一个正整数 n，将其分解为质因数的乘积，按从小到大输出每个质因子及其指数。', '一行，一个正整数 n。\n数据范围：2 ≤ n ≤ 10^9', '每行输出两个整数：质因子和对应的指数，按质因子从小到大排列。', 'Hard', 1000, 128, '试除法：从 2 到√n 遍历，能整除则统计指数，最后剩余大于 1 的数也是质因子。', 1, 0, 0);
INSERT INTO `problems` VALUES (112, '2026-06-03 19:49:41.559', '2026-06-04 00:14:59.685', NULL, 'KMP 字符串匹配', 'kmp-string-matching', '给定一个文本串 text 和一个模式串 pattern，找出 pattern 在 text 中所有出现的起始位置（下标从 0 开始）。', '两行，第一行文本串 text，第二行模式串 pattern。\n数据范围：1 ≤ pattern.length ≤ text.length ≤ 10^6，仅含小写字母。', '一行，输出所有匹配的起始位置，用空格分隔；无匹配输出空行。', 'Hard', 1000, 128, 'KMP 算法：先计算模式串的前缀函数（next 数组），再用双指针匹配，避免暴力匹配的回溯，时间复杂度 O (n+m)。', 1, 0, 0);
INSERT INTO `problems` VALUES (113, '2026-06-03 19:49:41.561', '2026-06-04 00:14:59.695', NULL, 'Manacher 算法：最长回文子串', 'manacher-longest-palindrome', '给定一个字符串 s，找到 s 中最长的回文子串，输出其长度。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 10^5', '一行，输出最长回文子串的长度。', 'Hard', 1000, 128, 'Manacher 算法：插入分隔符统一奇偶长度回文，维护中心和右边界，利用回文对称性加速计算，时间复杂度 O (n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (114, '2026-06-03 19:49:41.563', '2026-06-04 00:14:59.705', NULL, '字符串哈希：重复子串', 'string-hash-repeated-substring', '给定一个非空的字符串，判断它是否可以由它的一个子串重复多次构成。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 10^5', '可以由子串重复构成输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '字符串前缀哈希：枚举可能的子串长度，用哈希快速比较所有分段是否相等，时间复杂度 O (n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (115, '2026-06-03 19:49:41.565', '2026-06-04 00:14:59.715', NULL, 'Z 算法：Z 数组', 'z-algorithm', '给定一个字符串 s，计算 Z 数组。Z [i] 表示 s 和 s 从 i 开始的子串的最长公共前缀的长度。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 10^5', '一行，输出 Z 数组的所有元素，用空格分隔。', 'Hard', 1000, 128, 'Z 算法：维护匹配区间 [L,R]，利用已计算的 Z 值避免重复比较，时间复杂度 O (n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (116, '2026-06-03 19:49:41.566', '2026-06-04 00:14:59.724', NULL, 'AC 自动机：多模式匹配', 'ac-automaton', '给定 n 个模式串和一个文本串，统计有多少个模式串在文本串中出现过。', '第一行一个正整数 n，表示模式串数量。\n接下来 n 行，每行一个模式串。\n最后一行是文本串。\n数据范围：1 ≤ n ≤ 10^3，所有字符串总长度 ≤ 10^5。', '一行，输出在文本串中出现的模式串数量。', 'Hard', 1000, 128, 'AC 自动机：Trie 树 + 失配指针，构建失败指针后遍历文本串，匹配所有模式串，时间复杂度线性。', 1, 0, 0);
INSERT INTO `problems` VALUES (117, '2026-06-03 19:49:41.568', '2026-06-04 00:14:59.733', NULL, '最小表示法', 'minimal-string-rotation', '给定一个字符串 s，求它的所有循环同构串中字典序最小的那个的起始位置（下标从 0 开始）。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 10^5', '一行，输出最小表示的起始下标。', 'Hard', 1000, 128, '最小表示法：双指针比较两个起始位置的循环串，跳过不可能成为最小值的位置，时间复杂度 O (n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (118, '2026-06-03 19:49:41.570', '2026-06-04 00:14:59.742', NULL, '后缀数组', 'suffix-array', '给定一个字符串 s，计算它的后缀数组 SA。SA [i] 表示将所有后缀按字典序排序后，第 i 个后缀的起始下标。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 10^3', '一行，输出后缀数组 SA 的所有元素，用空格分隔。', 'Hard', 1000, 128, '倍增法构造后缀数组，按长度倍增排序后缀，利用基数排序优化时间复杂度。', 1, 0, 0);
INSERT INTO `problems` VALUES (119, '2026-06-03 19:49:41.571', '2026-06-04 00:14:59.752', NULL, '计算几何：叉积与线段相交', 'segment-intersection', '给定两条线段的端点坐标，判断两条线段是否相交（包含端点接触）。', '第一行四个整数 x1 y1 x2 y2，表示第一条线段的两个端点。\n第二行四个整数 x3 y3 x4 y4，表示第二条线段的两个端点。\n坐标范围：-10^4 ≤ 所有坐标 ≤ 10^4', '相交输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '快速排斥实验 + 跨立实验：先判断 bounding box 是否相交，再用叉积判断两个线段是否互相跨立。', 1, 0, 0);
INSERT INTO `problems` VALUES (120, '2026-06-03 19:49:41.573', '2026-06-04 00:14:59.764', NULL, '计算几何：凸包', 'convex-hull', '给定平面上 n 个点，求这些点的凸包，输出凸包上的点的数量。', '第一行一个正整数 n，表示点的数量。\n接下来 n 行，每行两个整数 x y，表示点的坐标。\n数据范围：3 ≤ n ≤ 10^4，所有点不重合。', '一行，输出凸包上的点的数量。', 'Hard', 1000, 128, 'Graham 扫描法：先找最左下的点，按极角排序，用栈维护凸包，叉积判断是否弹出栈顶。', 1, 0, 0);
INSERT INTO `problems` VALUES (121, '2026-06-03 19:49:41.575', '2026-06-04 00:14:59.773', NULL, '计算几何：多边形面积', 'polygon-area', '给定一个简单多边形的 n 个顶点坐标（按顺时针或逆时针顺序），计算多边形的面积。', '第一行一个正整数 n，表示多边形顶点数。\n接下来 n 行，每行两个整数 x y，表示顶点坐标。\n数据范围：3 ≤ n ≤ 100', '一行，输出多边形面积，保留 1 位小数。', 'Hard', 1000, 128, '鞋带公式：面积 = 1/2 * |sum (xi*yi+1 - xi+1*yi)|，其中 xn+1=x1, yn+1=y1。', 1, 0, 0);
INSERT INTO `problems` VALUES (122, '2026-06-03 19:49:41.577', '2026-06-04 00:14:59.782', NULL, '计算几何：点在多边形内', 'point-in-polygon', '给定一个简单多边形和一个点，判断该点是否在多边形内部（包含边界）。', '第一行一个正整数 n，表示多边形顶点数。\n接下来 n 行，每行两个整数 x y，表示多边形顶点坐标。\n最后一行两个整数 px py，表示待判断的点。\n数据范围：3 ≤ n ≤ 100', '点在多边形内或边界上输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '射线法：从该点向右水平发射一条射线，统计与多边形边的交点数，奇数在内部，偶数在外部，注意边界特殊情况。', 1, 0, 0);
INSERT INTO `problems` VALUES (123, '2026-06-03 19:49:41.579', '2026-06-04 00:14:59.791', NULL, '计算几何：最近点对', 'closest-pair-of-points', '给定平面上 n 个点，找出其中距离最近的两个点，输出它们的距离的平方（避免浮点数误差）。', '第一行一个正整数 n，表示点的数量。\n接下来 n 行，每行两个整数 x y，表示点的坐标。\n数据范围：2 ≤ n ≤ 10^5，所有点不重合。', '一行，输出最近点对距离的平方。', 'Hard', 1000, 128, '分治法：按 x 坐标排序，递归求左右子区域最近距离，再检查中间带状区域的点对，时间复杂度 O (nlogn)。', 1, 0, 0);
INSERT INTO `problems` VALUES (124, '2026-06-03 19:49:41.581', '2026-06-04 00:14:59.800', NULL, '最大流 Dinic 算法', 'max-flow-dinic', '给定一个有向图，包含 n 个点和 m 条边，每条边有容量。求从源点 s 到汇点 t 的最大流。', '第一行四个正整数 n、m、s、t，n 是点数，m 是边数，s 是源点，t 是汇点。\n接下来 m 行，每行三个整数 u、v、c，表示从 u 到 v 的有向边，容量为 c。\n数据范围：1 ≤ n ≤ 1000，1 ≤ m ≤ 10000，1 ≤ c ≤ 10^9。', '一行，输出 s 到 t 的最大流。', 'Hard', 1000, 128, 'Dinic 算法：BFS 分层建残量网络，DFS 多路增广，重复直到无法增广，是目前最常用的最大流算法。', 1, 0, 0);
INSERT INTO `problems` VALUES (125, '2026-06-03 19:49:41.585', '2026-06-04 00:14:59.810', NULL, '二分图最大匹配', 'bipartite-matching', '给定一个二分图，左边 n 个点，右边 m 个点，共 k 条边，求二分图的最大匹配数。', '第一行三个正整数 n、m、k，分别是左部点数、右部点数、边数。\n接下来 k 行，每行两个整数 u、v，表示左部 u 和右部 v 之间有边。\n数据范围：1 ≤ n, m ≤ 500，1 ≤ k ≤ 10^4。', '一行，输出最大匹配数。', 'Hard', 1000, 128, '匈牙利算法：遍历每个左部点，DFS 寻找增广路，时间复杂度 O (nk)。', 1, 0, 0);
INSERT INTO `problems` VALUES (126, '2026-06-03 19:49:41.587', '2026-06-04 00:14:59.820', NULL, '强连通分量 Tarjan 算法', 'strongly-connected-components', '给定一个有向图，求图中强连通分量的数量。强连通分量定义：分量中任意两个点互相可达。', '第一行两个正整数 n 和 m，n 是点数，m 是边数。\n接下来 m 行，每行两个整数 u、v，表示从 u 到 v 的有向边。\n数据范围：1 ≤ n ≤ 10^4，1 ≤ m ≤ 10^5。', '一行，输出强连通分量的数量。', 'Hard', 1000, 128, 'Tarjan 算法：DFS 遍历，用 dfn 和 low 数组记录访问时间和能到达的最早时间，栈维护当前连通分量，找到强连通分量时出栈计数。', 1, 0, 0);
INSERT INTO `problems` VALUES (127, '2026-06-03 19:49:41.588', '2026-06-04 00:14:59.830', NULL, '最小费用最大流', 'min-cost-max-flow', '给定一个有向图，每条边有容量和单位流量费用，求从 s 到 t 的最大流，以及在最大流前提下的最小费用。', '第一行四个正整数 n、m、s、t。\n接下来 m 行，每行四个整数 u、v、c、w，表示 u 到 v 的边，容量 c，单位费用 w。\n数据范围：1 ≤ n ≤ 500，1 ≤ m ≤ 10000。', '一行，输出两个整数：最大流、最小费用，用空格分隔。', 'Hard', 1000, 128, 'SPFA 找最短增广路（费用为权），沿最短路增广，重复直到无增广路。', 1, 0, 0);
INSERT INTO `problems` VALUES (128, '2026-06-03 19:49:41.590', '2026-06-04 00:14:59.840', NULL, '2-SAT 问题', '2-sat', '给定 n 个布尔变量和 m 个约束条件，每个约束是两个变量的或关系（a∨b），判断是否存在一组变量赋值满足所有约束。', '第一行两个正整数 n 和 m，n 是变量数，m 是约束数。\n接下来 m 行，每行四个整数 a、va、b、vb，表示约束：(a=va) ∨ (b=vb)，va 和 vb 为 0 或 1。\n数据范围：1 ≤ n ≤ 1000，1 ≤ m ≤ 10^4。', '存在满足条件的赋值输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '2-SAT 标准解法：每个变量拆成两个点（真和假），约束转化为蕴含边，Tarjan 求强连通分量，若某个变量的真假在同一分量则无解。', 1, 0, 0);
INSERT INTO `problems` VALUES (129, '2026-06-03 19:49:41.592', '2026-06-04 00:14:59.850', NULL, '割点与桥', 'cut-vertices-and-bridges', '给定一个无向连通图，求图中割点的数量和桥的数量。割点：删除该点后图不连通；桥：删除该边后图不连通。', '第一行两个正整数 n 和 m，n 是点数，m 是边数。\n接下来 m 行，每行两个整数 u、v，表示无向边。\n数据范围：1 ≤ n ≤ 20000，1 ≤ m ≤ 100000。', '一行，输出两个整数：割点数量、桥的数量，用空格分隔。', 'Hard', 1000, 128, 'Tarjan 算法：DFS 遍历，用 dfn 和 low 数组，割点判断：根节点有≥2 个子树，非根节点 low [v]≥dfn [u]；桥判断：low [v]>dfn [u]。', 1, 0, 0);
INSERT INTO `problems` VALUES (130, '2026-06-03 22:34:19.675', '2026-06-04 00:14:59.860', NULL, '区间 DP：石子合并', 'stone-merging', '有 N 堆石子排成一排，每堆石子有一定的数量。现要将 N 堆石子合并成为一堆。合并的过程只能每次将相邻的两堆石子合并成一堆，每次合并花费的代价为这两堆石子的和，经过 N-1 次合并后成为一堆。求出总的最小代价。', '第一行一个正整数 N，表示石子堆数。\n第二行 N 个正整数，表示每堆石子的数量。\n数据范围：1 ≤ N ≤ 300', '一行，输出合并的最小总代价。', 'Hard', 1000, 128, '区间 DP：dp [i][j] 表示合并第 i 到 j 堆石子的最小代价，dp [i][j] = min (dp [i][k] + dp [k+1][j]) + sum (i,j)，k 从 i 到 j-1，前缀和优化区间和计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (131, '2026-06-03 22:34:19.678', '2026-06-04 00:14:59.869', NULL, '树形 DP：树的直径', 'tree-diameter', '给定一棵无根树，求树的直径长度（树中任意两个节点之间的最长路径的边数）。', '第一行一个正整数 N，表示节点数。\n接下来 N-1 行，每行两个整数 u 和 v，表示树的边。\n数据范围：1 ≤ N ≤ 10^5', '一行，输出树的直径长度。', 'Hard', 1000, 128, '两次 DFS：第一次任意节点 DFS 找最远点 A，第二次从 A 点 DFS 找最远点 B，A 到 B 的距离即为直径；也可用树形 DP，每个节点维护最长和次长子链长度。', 1, 0, 0);
INSERT INTO `problems` VALUES (132, '2026-06-03 22:34:19.679', '2026-06-04 00:14:59.876', NULL, '状压 DP：旅行商问题 TSP', 'travelling-salesman-problem', '给定 n 个城市和城市之间的距离，一个旅行商从城市 0 出发，要经过所有城市恰好一次，最后回到起点，求最短路径长度。', '第一行一个正整数 n，表示城市数。\n接下来 n 行，每行 n 个整数，表示城市间的距离矩阵。\n数据范围：2 ≤ n ≤ 15', '一行，输出最短路径长度。', 'Hard', 1000, 128, '状压 DP：dp [mask][u] 表示经过 mask 集合中的城市，当前在 u 点的最短距离，mask 是二进制表示的城市集合，最终答案是 min (dp [(1<<n)-1][u] + dist [u][0])。', 1, 0, 0);
INSERT INTO `problems` VALUES (133, '2026-06-03 22:34:19.680', '2026-06-04 00:14:59.886', NULL, '数位 DP：统计 1 的个数', 'count-digit-one', '输入一个整数 n，统计所有小于等于 n 的非负整数中数字 1 出现的个数。', '一行，一个非负整数 n。\n数据范围：0 ≤ n ≤ 10^9', '一行，输出数字 1 出现的总次数。', 'Hard', 1000, 128, '数位 DP：按位处理，记录当前位、高位是否等于 n 的前缀、已经出现的 1 的个数，记忆化搜索所有合法数字。', 1, 0, 0);
INSERT INTO `problems` VALUES (134, '2026-06-03 22:34:19.682', '2026-06-04 00:14:59.895', NULL, '多重背包（二进制优化）', 'multiple-knapsack', '有 N 种物品和一个容量为 V 的背包。第 i 种物品最多有 s [i] 件可用，每件体积是 v [i]，价值是 w [i]。求解将哪些物品装入背包可使这些物品的体积总和不超过背包容量，且价值总和最大。', '第一行两个正整数 N 和 V。\n接下来 N 行，每行三个整数 v [i], w [i], s [i]，分别是体积、价值、数量。\n数据范围：1 ≤ N ≤ 1000，1 ≤ V ≤ 2000', '一行，输出最大价值。', 'Hard', 1000, 128, '二进制优化：将每种物品的数量拆分为 2 的幂次和，转化为 0-1 背包问题，时间复杂度从 O (NVS) 优化到 O (NV logS)。', 1, 0, 0);
INSERT INTO `problems` VALUES (135, '2026-06-03 22:34:19.684', '2026-06-04 00:14:59.903', NULL, '最长回文子序列', 'longest-palindromic-subsequence', '给定一个字符串 s，找到其中最长的回文子序列，并返回该序列的长度。子序列定义为：不改变剩余字符顺序的情况下，删除某些字符或者不删除任何字符形成的一个序列。', '一行，一个字符串 s。\n数据范围：1 ≤ s.length ≤ 1000', '一行，输出最长回文子序列的长度。', 'Hard', 1000, 128, '区间 DP：dp [i][j] 表示 s [i..j] 的最长回文子序列长度，s [i]==s [j] 时 dp [i][j]=dp [i+1][j-1]+2，否则 dp [i][j]=max (dp [i+1][j], dp [i][j-1])。', 1, 0, 0);
INSERT INTO `problems` VALUES (136, '2026-06-03 22:34:19.685', '2026-06-04 00:14:59.913', NULL, '概率 DP：掷骰子', 'dice-probability', '掷 n 个骰子，每个骰子点数 1-6，求所有骰子点数和为 s 的概率。', '一行，两个正整数 n 和 s。\n数据范围：1 ≤ n ≤ 100，n ≤ s ≤ 6n', '一行，输出概率，保留 5 位小数。', 'Hard', 1000, 128, 'DP：dp [i][j] 表示 i 个骰子和为 j 的方案数，dp [i][j] = sum (dp [i-1][j-k]) for k=1 到 6，最终概率 = dp [n][s] / 6^n。', 1, 0, 0);
INSERT INTO `problems` VALUES (137, '2026-06-03 22:34:19.686', '2026-06-04 00:14:59.922', NULL, '二叉树最大路径和', 'binary-tree-max-path-sum', '二叉树中的路径被定义为一条节点序列，序列中每对相邻节点之间都存在一条边。同一个节点在一条路径序列中至多出现一次。该路径至少包含一个节点，且不一定经过根节点。路径和是路径中各节点值的总和。给你一个二叉树的根节点，返回其最大路径和。', '第一行一个正整数 n，表示节点数。\n第二行 n 个整数，表示二叉树的层序遍历，-1 表示空节点。\n数据范围：1 ≤ n ≤ 3 * 10^4', '一行，输出最大路径和。', 'Hard', 1000, 128, '树形 DP：递归计算每个节点的最大贡献值（以该节点为起点向下的最大路径和），同时更新全局最大路径和（当前节点值 + 左贡献 + 右贡献）。', 1, 0, 0);
INSERT INTO `problems` VALUES (138, '2026-06-03 22:34:19.688', '2026-06-04 00:14:59.931', NULL, '巴什博弈', 'bash-game', '两个人玩取石子游戏，一共有 n 个石子，每次最多取 m 个，最少取 1 个，最后取完石子的人获胜。假设两人都采取最优策略，问先手是否必胜。', '一行，两个正整数 n 和 m。\n数据范围：1 ≤ n, m ≤ 10^9', '先手必胜输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, '巴什博弈结论：n % (m+1) != 0 时先手必胜，否则必败。', 1, 0, 0);
INSERT INTO `problems` VALUES (139, '2026-06-03 22:34:19.690', '2026-06-04 00:14:59.939', NULL, 'Nim 游戏', 'nim-game', 'n 堆石子，两个人轮流取，每次可以从任意一堆中取任意多个石子（至少 1 个），最后取完的人获胜。两人都采取最优策略，问先手是否必胜。', '第一行一个正整数 n。\n第二行 n 个正整数，表示每堆石子的数量。\n数据范围：1 ≤ n ≤ 10^5', '先手必胜输出\"Yes\"，否则输出\"No\"。', 'Medium', 1000, 128, 'Nim 游戏结论：所有堆石子数的异或和不等于 0 时先手必胜，等于 0 时必败。', 1, 0, 0);
INSERT INTO `problems` VALUES (140, '2026-06-03 22:34:19.691', '2026-06-04 00:14:59.948', NULL, '威佐夫博弈', 'wythoff-game', '两堆石子，两个人轮流取，有两种取法：1. 从任意一堆取任意多个；2. 从两堆取相同数量的石子。最后取完的人获胜，问先手是否必胜。', '一行，两个正整数 a 和 b，表示两堆石子的数量。\n数据范围：0 ≤ a, b ≤ 10^9', '先手必胜输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '威佐夫博弈结论：令 k=abs (a-b)，黄金分割比 φ=(1+√5)/2，若 min (a,b) == floor (k*φ) 则先手必败，否则必胜。', 1, 0, 0);
INSERT INTO `problems` VALUES (141, '2026-06-03 22:34:19.692', '2026-06-04 00:14:59.957', NULL, '斐波那契博弈', 'fibonacci-game', '有 n 个石子，两个人轮流取，先手第一次可以取任意多个但不能取完，之后每次取的石子数不能超过上一次取的 2 倍，最后取完的人获胜，问先手是否必胜。', '一行，一个正整数 n。\n数据范围：2 ≤ n ≤ 10^9', '先手必胜输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, '斐波那契博弈结论：n 是斐波那契数时先手必败，否则必胜。', 1, 0, 0);
INSERT INTO `problems` VALUES (142, '2026-06-03 22:34:19.694', '2026-06-04 00:14:59.966', NULL, 'SG 函数：取石子游戏', 'sg-function-game', 'n 堆石子，每次只能从一堆中取 1、2 或 3 个石子，最后取完的人获胜，问先手是否必胜。', '第一行一个正整数 n。\n第二行 n 个正整数，表示每堆石子数。\n数据范围：1 ≤ n ≤ 100，1 ≤ 每堆石子数 ≤ 1000', '先手必胜输出\"Yes\"，否则输出\"No\"。', 'Hard', 1000, 128, 'SG 函数：sg [x] = mex {sg [x-1], sg [x-2], sg [x-3]}，所有堆 SG 值的异或和非零则先手必胜。', 1, 0, 0);
INSERT INTO `problems` VALUES (143, '2026-06-03 22:34:19.695', '2026-06-04 00:14:59.974', NULL, '卡特兰数', 'catalan-number', '求第 n 个卡特兰数。卡特兰数应用：括号匹配数、二叉树结构数、出栈序列数等。卡特兰数公式：C (n) = C (2n,n)/(n+1)。', '一行，一个非负整数 n。\n数据范围：0 ≤ n ≤ 20', '一行，输出第 n 个卡特兰数。', 'Medium', 1000, 128, '递推公式：C (0)=1，C (n+1) = sum (C (i)*C (n-i)) for i=0 到 n，也可用组合数公式计算。', 1, 0, 0);
INSERT INTO `problems` VALUES (144, '2026-06-03 22:34:19.697', '2026-06-04 00:14:59.985', NULL, '错排问题', 'derangement', 'n 个元素的排列，要求每个元素都不在自己原来的位置上，求这样的排列的数量（错排数）。', '一行，一个正整数 n。\n数据范围：1 ≤ n ≤ 20', '一行，输出错排数。', 'Medium', 1000, 128, '错排递推公式：D (n) = (n-1) * (D (n-1) + D (n-2))，D (1)=0，D (2)=1。', 1, 0, 0);
INSERT INTO `problems` VALUES (145, '2026-06-03 22:34:19.699', '2026-06-04 00:14:59.994', NULL, '组合数取模', 'combination-mod', '求组合数 C (n, k) mod p，p 是质数。', '一行，三个正整数 n、k、p，p 是质数。\n数据范围：0 ≤ k ≤ n ≤ 10^18，p ≤ 10^5', '一行，输出 C (n,k) mod p 的结果。', 'Hard', 1000, 128, '卢卡斯定理：C (n,k) mod p = C (n% p, k% p) * C (n/p, k/p) mod p，预处理阶乘和逆元快速计算小范围组合数。', 1, 0, 0);
INSERT INTO `problems` VALUES (146, '2026-06-03 22:34:19.701', '2026-06-04 00:15:00.003', NULL, '容斥原理：计数', 'inclusion-exclusion-principle', '求 1 到 n 中能被 a 或 b 整除的数的个数。', '一行，三个正整数 n、a、b。\n数据范围：1 ≤ n, a, b ≤ 10^9', '一行，输出符合条件的数的个数。', 'Hard', 1000, 128, '容斥原理：个数 = floor (n/a) + floor (n/b) - floor (n/lcm (a,b))，lcm 是最小公倍数。', 1, 0, 0);
INSERT INTO `problems` VALUES (147, '2026-06-03 22:34:19.703', '2026-06-04 00:15:00.012', NULL, '隔板法：不定方程解数', 'stars-and-bars', '求不定方程 x1 + x2 + ... + xk = n 的正整数解的个数，其中 xi ≥ 1。', '一行，两个正整数 n 和 k。\n数据范围：1 ≤ k ≤ n ≤ 30', '一行，输出解的个数。', 'Medium', 1000, 128, '隔板法：n 个相同的球分成 k 组，每组至少 1 个，解数为 C (n-1, k-1)。', 1, 0, 0);
INSERT INTO `problems` VALUES (148, '2026-06-03 22:34:19.705', '2026-06-04 00:15:00.021', NULL, 'ST 表：区间最值查询', 'sparse-table-rmq', '给定一个长度为 n 的数组，回答 q 次查询，每次查询区间 [l, r] 的最大值。', '第一行两个正整数 n 和 q。\n第二行 n 个整数，表示数组。\n接下来 q 行，每行两个整数 l 和 r，表示查询区间（下标从 0 开始）。\n数据范围：1 ≤ n, q ≤ 10^5', '每个查询输出一行对应的最大值。', 'Hard', 1000, 128, 'ST 表：预处理 f [k][i] 表示从 i 开始长度为 2^k 的区间的最大值，O (nlogn) 预处理，O (1) 回答每次查询。', 1, 0, 0);
INSERT INTO `problems` VALUES (149, '2026-06-03 22:34:19.708', '2026-06-04 00:15:00.031', NULL, '树上差分：路径加和', 'tree-difference', '给定一棵 n 个节点的树，初始所有节点权值为 0。进行 m 次操作：将 u 到 v 路径上的所有节点权值加 1。求最终所有节点的权值。', '第一行两个正整数 n 和 m。\n接下来 n-1 行，每行两个整数 u 和 v，表示树的边。\n接下来 m 行，每行两个整数 u 和 v，表示路径操作。\n数据范围：1 ≤ n, m ≤ 10^5', '一行，输出 1 到 n 号节点的最终权值，用空格分隔。', 'Hard', 1000, 128, '树上差分：diff [u]+1，diff [v]+1，diff [lca (u,v)]-1，diff [fa [lca]]-1，最后 DFS 求子树和即为每个节点权值。', 1, 0, 0);
INSERT INTO `problems` VALUES (150, '2026-06-03 22:34:19.713', '2026-06-04 00:15:00.041', NULL, '莫队算法：区间众数', 'mo-algorithm-mode', '给定一个长度为 n 的数组，回答 q 次查询，每次查询区间 [l, r] 中出现次数最多的数的出现次数。', '第一行两个正整数 n 和 q。\n第二行 n 个整数，表示数组。\n接下来 q 行，每行两个整数 l 和 r（下标从 0 开始）。\n数据范围：1 ≤ n, q ≤ 50000', '每个查询输出一行对应的最大出现次数。', 'Hard', 1000, 128, '莫队算法：将查询分块排序，双指针移动维护当前区间的元素计数和最大次数，时间复杂度 O (n√n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (151, '2026-06-03 22:34:19.715', '2026-06-04 00:15:00.050', NULL, '分块算法：区间更新查询', 'sqrt-decomposition', '给定一个长度为 n 的数组，支持两种操作：1. 区间 [l, r] 所有元素加 val；2. 查询区间 [l, r] 的和。', '第一行两个正整数 n 和 q。\n第二行 n 个整数，表示初始数组。\n接下来 q 行，每行第一个数为操作类型：\n- 1 l r val：区间加 val\n- 2 l r：查询区间和\n数据范围：1 ≤ n, q ≤ 10^5', '每个查询输出一行对应的区间和。', 'Hard', 1000, 128, '分块算法：将数组分成√n 块，整块操作打懒标记，散块暴力修改，时间复杂度 O (q√n)。', 1, 0, 0);
INSERT INTO `problems` VALUES (152, '2026-06-03 22:34:19.716', '2026-06-04 00:15:00.058', NULL, '灯泡开关问题', 'bulb-switcher', '初始时有 n 个灯泡关闭。第 1 轮，所有灯泡打开；第 2 轮，每 2 个关闭第 2 个；第 3 轮，每 3 个切换第 3 个状态；第 i 轮，每 i 个切换第 i 个状态。n 轮后，有多少个灯泡是亮的？', '一行，一个正整数 n。\n数据范围：0 ≤ n ≤ 10^9', '一行，输出亮着的灯泡数量。', 'Medium', 1000, 128, '只有完全平方数位置的灯泡会被切换奇数次，最终亮着，答案是 floor (sqrt (n))。', 1, 0, 0);
INSERT INTO `problems` VALUES (153, '2026-06-03 22:34:19.717', '2026-06-04 00:15:00.071', NULL, '最少操作使数组相等', 'minimum-moves-to-equal-array', '给定一个长度为 n 的非空整数数组，每次操作可以将 n-1 个元素加 1，求最少多少次操作可以让所有元素相等。', '第一行一个正整数 n。\n第二行 n 个整数，表示数组。\n数据范围：1 ≤ n ≤ 10^5', '一行，输出最少操作次数。', 'Medium', 1000, 128, '等价于每次将 1 个元素减 1，答案是所有元素减去最小值的和。', 1, 0, 0);
INSERT INTO `problems` VALUES (154, '2026-06-03 22:34:19.719', '2026-06-04 00:15:00.080', NULL, '构造最小字典序数组', 'construct-smallest-lex-array', '给定一个数组，你可以交换任意两个相邻元素最多 k 次，求能得到的最小字典序的数组。', '第一行两个正整数 n 和 k。\n第二行 n 个整数，表示数组。\n数据范围：1 ≤ n ≤ 1000，0 ≤ k ≤ 10^6', '一行，输出最小字典序数组，元素用空格分隔。', 'Medium', 1000, 128, '贪心：每次在当前位置开始的 k+1 个元素中选最小的，移到当前位置，k 减去移动的步数。', 1, 0, 0);
INSERT INTO `problems` VALUES (155, '2026-06-03 22:34:19.721', '2026-06-04 00:15:00.089', NULL, '表达式求值（四则运算）', 'expression-evaluation', '给定一个只包含整数、+、-、*、/ 和括号的合法表达式，计算表达式的值，除法取整。', '一行，一个合法的表达式字符串，不含空格。\n数据范围：表达式长度 ≤ 1000', '一行，输出表达式的值。', 'Medium', 1000, 128, '后缀表达式（逆波兰式）：用两个栈分别存运算符和操作数，按优先级计算，处理括号。', 1, 0, 0);
INSERT INTO `problems` VALUES (156, '2026-06-03 22:34:19.722', '2026-06-04 00:15:00.097', NULL, '日期差计算', 'date-difference', '给定两个日期（YYYY-MM-DD），计算两个日期之间相差的天数。', '两行，每行一个日期字符串，格式为 YYYY-MM-DD。', '一行，输出两个日期相差的天数（绝对值）。', 'Medium', 1000, 128, '计算每个日期到公元元年 1 月 1 日的天数，相减取绝对值，注意闰年判断。', 1, 0, 0);
INSERT INTO `problems` VALUES (157, '2026-06-03 22:34:19.724', '2026-06-04 00:15:00.107', NULL, '任意进制转换', 'base-conversion', '将一个 a 进制的数转换为 b 进制的数。', '第一行三个整数 n、a、b，n 是 a 进制的数字字符串（仅含 0-9 和 A-Z，A=10，Z=35）。\n数据范围：2 ≤ a, b ≤ 36', '一行，输出 b 进制的结果，字母大写。', 'Medium', 1000, 128, '先转十进制，再转目标进制，除基取余，倒序输出。', 1, 0, 0);
INSERT INTO `problems` VALUES (158, '2026-06-03 22:34:19.726', '2026-06-04 00:15:00.116', NULL, '模拟扫雷', 'minesweeper', '给定一个扫雷棋盘，M 表示地雷，. 表示空地，输出每个空地周围 8 个方向的地雷数，地雷位置保持 M。', '第一行两个正整数 n 和 m，表示棋盘行列数。\n接下来 n 行，每行 m 个字符，为 M 或.。', '输出 n 行，处理后的扫雷棋盘。', 'Medium', 1000, 128, '遍历每个空地，统计周围 8 格的地雷数量，地雷位置直接输出 M。', 1, 0, 0);
INSERT INTO `problems` VALUES (159, '2026-06-03 22:34:19.727', '2026-06-04 00:15:00.123', NULL, '文本单词统计', 'word-count', '给定一段英文文本，统计每个单词出现的次数，按单词字典序输出，单词不区分大小写，输出全小写。', '一行，英文文本，仅包含字母、空格和标点。', '每行输出一个单词和出现次数，用空格分隔，按字典序排列。', 'Medium', 1000, 128, '先将所有字符转小写，分割单词，过滤标点，用哈希表统计次数，排序输出。', 1, 0, 0);
INSERT INTO `problems` VALUES (160, '2026-06-03 22:34:19.728', '2026-06-04 00:15:00.132', NULL, '扑克牌排序', 'poker-sorting', '给定 n 张扑克牌，按规则排序：先按花色（黑桃 > 红桃 > 梅花 > 方块），同花色按点数从大到小（A>K>Q>J>10>...>2）。', '第一行一个正整数 n。\n第二行 n 个字符串，表示扑克牌，如 SA（黑桃 A）、H10（红桃 10）、DQ（方块 Q）、CJ（梅花 J）。', '一行，输出排序后的扑克牌，用空格分隔。', 'Medium', 1000, 128, '给花色和点数分配权重，自定义排序规则。', 1, 0, 0);
INSERT INTO `problems` VALUES (161, '2026-06-03 22:34:19.730', '2026-06-04 00:15:00.141', NULL, '模拟计算器', 'simulate-calculator', '实现一个支持加减乘除、括号、小数的计算器，输入合法表达式，输出结果，保留 2 位小数。', '一行，合法的表达式字符串。', '一行，输出计算结果，保留 2 位小数。', 'Hard', 1000, 128, '后缀表达式法，处理小数和运算符优先级，注意浮点数精度。', 1, 0, 0);
INSERT INTO `problems` VALUES (162, '2026-06-03 22:34:19.732', '2026-06-04 00:15:00.151', NULL, '可持久化线段树：区间第 k 小', 'persistent-segment-tree-kth', '给定一个长度为 n 的数组，回答 q 次查询：区间 [l, r] 中第 k 小的数是多少。', '第一行两个正整数 n 和 q。\n第二行 n 个整数，表示数组。\n接下来 q 行，每行三个整数 l、r、k（下标从 1 开始）。\n数据范围：1 ≤ n, q ≤ 10^5', '每个查询输出一行对应的第 k 小数。', 'Hard', 1000, 128, '主席树（可持久化权值线段树）：离散化后，每个前缀建一棵权值线段树，查询时用 r 版本减 l-1 版本的线段树，二分找第 k 小。', 1, 0, 0);
INSERT INTO `problems` VALUES (163, '2026-06-03 22:34:19.733', '2026-06-04 00:15:00.160', NULL, '启发式合并：子树查询', 'heuristic-merge-dsu-on-tree', '给定一棵 n 个节点的树，每个节点有一个颜色，求每个节点的子树中不同颜色的数量。', '第一行一个正整数 n。\n第二行 n 个整数，表示每个节点的颜色。\n接下来 n-1 行，每行两个整数 u 和 v，表示树的边。\n数据范围：1 ≤ n ≤ 10^5', '一行，输出 1 到 n 号节点子树的不同颜色数，用空格分隔。', 'Hard', 1000, 128, 'DSU on Tree（树上启发式合并）：保留重儿子的信息，暴力合并轻儿子，时间复杂度 O (nlogn)。', 1, 0, 0);
INSERT INTO `problems` VALUES (164, '2026-06-03 22:34:19.735', '2026-06-04 00:15:00.173', NULL, '构造回文串', 'construct-palindrome', '给定一个字符串，判断是否可以重排字符构成回文串，如果可以输出任意一个回文串，否则输出\"No\"。', '一行，一个仅含小写字母的字符串。\n数据范围：1 ≤ 长度 ≤ 1000', '如果可以构造，输出字典序最小的回文串；否则输出 No。', 'Medium', 1000, 128, '统计字符出现次数，最多只能有一个字符出现奇数次，奇数长度回文。', 1, 0, 0);
INSERT INTO `problems` VALUES (165, '2026-06-03 22:34:19.746', '2026-06-04 00:15:00.182', NULL, '约瑟夫环进阶', 'josephus-advanced', 'n 个人围成一圈，从第一个人开始报数，报到 m 的人出列，下一个人重新从 1 开始报数，求最后剩下的人的原始编号（从 1 开始）。', '一行，两个正整数 n 和 m。\n数据范围：1 ≤ n ≤ 10^6，1 ≤ m ≤ 10^9', '一行，输出最后剩下的人的编号。', 'Hard', 1000, 128, '约瑟夫环递推：f (n) = (f (n-1) + m) % n，f (1)=0，最终结果 + 1。', 1, 0, 0);
